// ---- file: tv80.v0.v ----
module tv80_alu (/*AUTOARG*/
  // Outputs
  Q, F_Out, 
  // Inputs
  Arith16, Z16, ALU_Op, IR, ISet, BusA, BusB, F_In
  );

  parameter		Mode   = 0;
  parameter		Flag_C = 0;
  parameter		Flag_N = 1;
  parameter		Flag_P = 2;
  parameter		Flag_X = 3;
  parameter		Flag_H = 4;
  parameter		Flag_Y = 5;
  parameter		Flag_Z = 6;
  parameter		Flag_S = 7;

  input 		Arith16;
  input 		Z16;
  input [3:0]           ALU_Op ;
  input [5:0]           IR;
  input [1:0]           ISet;
  input [7:0]           BusA;
  input [7:0]           BusB;
  input [7:0]           F_In;
  output [7:0]          Q;
  output [7:0]          F_Out;
  reg [7:0]             Q;
  reg [7:0]             F_Out;

  wire                  UseCarry;
  wire                  SubOp;
  wire                  AddCarryIn;
  wire [7:0]            AddB;
  wire [8:0]            AddFull;
  wire [4:0]            AddLow;
  wire [7:0]            Q_v;
  wire                  Carry_v;
  wire                  HalfCarry_v;
  wire                  OverFlow_v;
  wire [7:0]            BitMask;

  assign BitMask    = 8'b00000001 << IR[5:3];
  assign UseCarry   = ~ALU_Op[2] & ALU_Op[0];
  assign SubOp      = ALU_Op[1];
  assign AddB       = BusB ^ {8{SubOp}};
  assign AddCarryIn = SubOp ^ (UseCarry & F_In[Flag_C]);

  assign AddFull     = {1'b0, BusA} + {1'b0, AddB} + AddCarryIn;
  assign AddLow      = {1'b0, BusA[3:0]} + {1'b0, AddB[3:0]} + AddCarryIn;
  assign Q_v         = AddFull[7:0];
  assign Carry_v     = AddFull[8];
  assign HalfCarry_v = AddLow[4];
  assign OverFlow_v  = ~(BusA[7] ^ AddB[7]) & (BusA[7] ^ AddFull[7]);

  wire        daa_en;
  wire [7:0]  daa_a;
  wire        daa_fh;
  wire        daa_fc;
  wire        daa_fn;
  wire        daa_low_gt9;
  wire        daa_low_gt5;
  wire        daa_low_adj;
  wire [8:0]  daa_add_low;
  wire        daa_add_high_adj;
  wire [8:0]  daa_add_final;
  wire [7:0]  daa_sub_low;
  wire        daa_sub_high_adj;
  wire [8:0]  daa_sub_final;
  wire [8:0]  daa_final;
  wire        daa_hflag;

  assign daa_en            = (ALU_Op == 4'b1100);
  assign daa_a             = BusA & {8{daa_en}};
  assign daa_fh            = F_In[Flag_H] & daa_en;
  assign daa_fc            = F_In[Flag_C] & daa_en;
  assign daa_fn            = F_In[Flag_N] & daa_en;

  assign daa_low_gt9       = daa_a[3:0] > 4'd9;
  assign daa_low_gt5       = daa_a[3:0] > 4'd5;
  assign daa_low_adj       = daa_low_gt9 | daa_fh;

  assign daa_add_low       = {1'b0, daa_a} + (daa_low_adj ? 9'd6 : 9'd0);
  assign daa_add_high_adj  = (daa_add_low[8:4] > 5'd9) | daa_fc;
  assign daa_add_final     = daa_add_low + (daa_add_high_adj ? 9'd96 : 9'd0);

  assign daa_sub_low       = daa_a - (daa_low_adj ? 8'd6 : 8'd0);
  assign daa_sub_high_adj  = (daa_a > 8'd153) | daa_fc;
  assign daa_sub_final     = daa_sub_high_adj ? ({1'b0, daa_sub_low} - 9'd352) :
                                                 {1'b0, daa_sub_low};

  assign daa_final         = daa_fn ? daa_sub_final : daa_add_final;
  assign daa_hflag         = daa_fn ? (daa_fh & ~daa_low_gt5) :
                                      daa_low_gt9;

  reg [7:0] Q_t;

  always @*
    begin
      Q_t = 8'hxx;

      F_Out = F_In;
      case (ALU_Op)
	4'b0000, 4'b0001, 4'b0010, 4'b0011,
        4'b0100, 4'b0101, 4'b0110, 4'b0111 :
          begin
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_C] = 1'b0;

	    case (ALU_Op[2:0])
	      3'b000, 3'b001 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_C] = Carry_v;
		  F_Out[Flag_H] = HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end

	      3'b010, 3'b011, 3'b111 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_N] = 1'b1;
		  F_Out[Flag_C] = ~Carry_v;
		  F_Out[Flag_H] = ~HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end

	      3'b100 :
                begin
		  Q_t[7:0] = BusA & BusB;
		  F_Out[Flag_H] = 1'b1;
                end

	      3'b101 :
                begin
		  Q_t[7:0] = BusA ^ BusB;
		  F_Out[Flag_H] = 1'b0;
                end

	      default :
                begin
		  Q_t[7:0] = BusA | BusB;
		  F_Out[Flag_H] = 1'b0;
                end
	    endcase

	    if (ALU_Op[2:0] == 3'b111) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end 
            else 
              begin
		F_Out[Flag_X] = Q_t[3];
		F_Out[Flag_Y] = Q_t[5];
	      end

	    if (~|Q_t[7:0]) 
              begin
		F_Out[Flag_Z] = 1'b1;
		if (Z16 == 1'b1) 
		  F_Out[Flag_Z] = F_In[Flag_Z];
	      end 
            else 
	      F_Out[Flag_Z] = 1'b0;

	    F_Out[Flag_S] = Q_t[7];

	    case (ALU_Op[2:0])
	      3'b000, 3'b001, 3'b010, 3'b011, 3'b111 :
                ;
	      default :
	        F_Out[Flag_P] = ~(^Q_t);
	    endcase

	    if (Arith16 == 1'b1) 
              begin
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
		F_Out[Flag_P] = F_In[Flag_P];
	      end
          end

	4'b1100 :
          begin
	    Q_t = daa_final[7:0];

	    F_Out[Flag_H] = daa_hflag;
	    F_Out[Flag_X] = daa_final[3];
	    F_Out[Flag_Y] = daa_final[5];
	    F_Out[Flag_C] = F_In[Flag_C] | daa_final[8];
	    F_Out[Flag_Z] = ~|daa_final[7:0];
	    F_Out[Flag_S] = daa_final[7];
	    F_Out[Flag_P] = ~(^daa_final);
          end

	4'b1101, 4'b1110 :
          begin
	    Q_t[7:4] = BusA[7:4];
	    if (ALU_Op[0] == 1'b1)
	      Q_t[3:0] = BusB[7:4];
            else
	      Q_t[3:0] = BusB[3:0];

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    if (~|Q_t[7:0])
	      F_Out[Flag_Z] = 1'b1;
            else
	      F_Out[Flag_Z] = 1'b0;
	    F_Out[Flag_S] = Q_t[7];
            F_Out[Flag_P] = ~(^Q_t);
          end

	4'b1001 :
          begin
	    Q_t[7:0] = BusB & BitMask;
	    F_Out[Flag_S] = Q_t[7];
	    if (~|Q_t[7:0]) 
              begin
		F_Out[Flag_Z] = 1'b1;
		F_Out[Flag_P] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
		F_Out[Flag_P] = 1'b0;
	      end
	    F_Out[Flag_H] = 1'b1;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = 1'b0;
	    F_Out[Flag_Y] = 1'b0;
	    if (IR[2:0] != 3'b110) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end
          end

	4'b1010 :
	  Q_t[7:0] = BusB | BitMask;

	4'b1011 :
	  Q_t[7:0] = BusB & ~BitMask;

	4'b1000 :
          begin
	    case (IR[5:3])
	      3'b000 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = BusA[7];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b010 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b001 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[0];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b011 :
                begin                        
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b100 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = 1'b0;
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b110 :
                begin
		  if (Mode == 3) 
                    begin
		      Q_t[7:4] = BusA[3:0];
		      Q_t[3:0] = BusA[7:4];
		      F_Out[Flag_C] = 1'b0;
		    end 
                  else 
                    begin
		      Q_t[7:1] = BusA[6:0];
		      Q_t[0] = 1'b1;
		      F_Out[Flag_C] = BusA[7];
		    end
                end

	      3'b101 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[7];
		  F_Out[Flag_C] = BusA[0];
                end

	      default :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = 1'b0;
		  F_Out[Flag_C] = BusA[0];
                end
	    endcase

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_S] = Q_t[7];
	    if (~|Q_t[7:0])
	      F_Out[Flag_Z] = 1'b1;
            else
	      F_Out[Flag_Z] = 1'b0;
            F_Out[Flag_P] = ~(^Q_t);

	    if (ISet == 2'b00) 
              begin
		F_Out[Flag_P] = F_In[Flag_P];
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
	      end
          end

	default :
	  ;
      endcase

      Q = Q_t;
    end

endmodule

