module uart_top_design (
    input wire clk,
    input wire rst,
    input wire [1:0] address,
    input wire [31:0] write_data,
    input wire we,
    output wire tx,
    input wire rx,
    input wire re,
    output reg [7:0] read_data
);

    localparam BAUD_DATA = 2'd0;
    localparam ENABLE    = 2'd1;
    localparam TX_DATA   = 2'd2;
    localparam RX_DATA   = 2'd3;

    reg [31:0] baud_division;
    reg enable;
    reg [7:0] data_out;
    wire [7:0] data_in;

    always @(*) begin
        if (rst) begin
            baud_division = 32'd0;
            enable        = 1'b0;
            data_out      = 8'd0;
        end else begin
            case (address)
                BAUD_DATA: begin
                    if (we)
                        baud_division = write_data;
                end
                ENABLE: begin
                    if (we)
                        enable = write_data[0];
                end
                TX_DATA: begin
                    if (we)
                        data_out = write_data[7:0];
                end
                RX_DATA: begin
                    if (re)
                        read_data = data_in;
                end
            endcase
        end
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk           (clk),
        .rst           (rst),
        .baud_division (baud_division),
        .en            (enable),
        .baud_tick     (baud_tick)
    );

    uart_tx uut_tx (
        .clk         (clk),
        .rst         (rst),
        .baud_tick   (baud_tick),
        .ext_data_in (data_out),
        .en          (enable),
        .tx          (tx)
    );

    uart_rx uut_rx (
        .clk          (clk),
        .rst          (rst),
        .baud_tick    (baud_tick),
        .rx           (rx),
        .ext_data_out (data_in)
    );

