module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;
    reg [13:0] baud_count;

    wire div_nonzero = (baud_division != 32'd0);
    wire div_small   = (baud_division[31:14] == 18'd0);
    wire [13:0] div_lo = baud_division[13:0];

    always @(posedge clk) begin
        if (rst) begin
            temp_en    <= 1'b0;
            delayed_en <= 1'b0;
        end else begin
            temp_en    <= en;
            delayed_en <= temp_en;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 14'd0;
            baud_tick  <= 1'b0;
        end else begin
            if (div_nonzero) begin
                if (en && !delayed_en) begin
                    baud_count <= 14'd1;
                    baud_tick  <= baud_tick;
                end else if (div_small && (baud_count == div_lo)) begin
                    baud_count <= 14'd0;
                    baud_tick  <= 1'b1;
                end else begin
                    if (!div_small) begin
                        if (baud_count != 14'h3fff)
                            baud_count <= baud_count + 14'd1;
                    end else if (baud_count < div_lo) begin
                        baud_count <= baud_count + 14'd1;
                    end
                    baud_tick <= 1'b0;
                end
            end else begin
                baud_count <= 14'd0;
                baud_tick  <= 1'b0;
            end
        end
    end

endmodule


module uart_rx (
    input clk,
    input rst,
    input baud_tick,
    input rx,
    output wire [7:0] ext_data_out
);

    localparam IDLE  = 2'b00;
    localparam START = 2'b01;
    localparam DATA  = 2'b11;
    localparam STOP  = 2'b10;

    reg [3:0] count_16;
    reg count_16_indication;

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    reg [1:0] current_state;

    assign ext_data_out = data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'd0;
            count_16_indication <= 1'b0;
        end else begin
            if (baud_tick) begin
                if (current_state == START) begin
                    if (&count_16[2:0]) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else if ((current_state == DATA) || (current_state == STOP)) begin
                    if (&count_16) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else begin
                    count_16 <= 4'd0;
                    count_16_indication <= 1'b0;
                end
            end else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 3'd0;
            count_8_indication <= 1'b0;
            data_save <= 8'd0;
        end else begin
            if (current_state == DATA) begin
                if (baud_tick && (&count_16)) begin
                    data_save <= {data_save[6:0], rx};
                    if (&count_8) begin
                        count_8 <= 3'd0;
                        count_8_indication <= 1'b1;
                    end else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                    end
                end else begin
                    count_8_indication <= 1'b0;
                end
            end else begin
                count_8 <= 3'd0;
                count_8_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            current_state <= IDLE;
        end else begin
            case (current_state)
                IDLE: begin
                    if (rx == 1'b0)
                        current_state <= START;
                end
                START: begin
                    if (count_16_indication && (rx == 1'b0))
                        current_state <= DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        current_state <= STOP;
                end
                STOP: begin
                    if (count_16_indication && (rx == 1'b1))
                        current_state <= IDLE;
                end
                default: begin
                    current_state <= IDLE;
                end
            endcase
        end
    end

endmodule


module uart_tx (
    input wire clk,
    input wire rst,
    input wire baud_tick,
    input wire [7:0] ext_data_in,
    input wire en,
    output reg tx
);

    localparam IDLE  = 2'b00;
    localparam START = 2'b01;
    localparam DATA  = 2'b11;
    localparam STOP  = 2'b10;

