    reg count_8_indication;
    reg [7:0] data_save;

    reg [1:0] current_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'd0;
            count_16_indication <= 1'b0;
        end else begin
            if (baud_tick) begin
                if (current_state != IDLE) begin
                    if (&count_16) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else begin
                    count_16 <= 4'd0;
                    count_16_indication <= 1'b0;
                end
            end else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst) begin
            if (current_state == DATA) begin
                if (baud_tick && (&count_16)) begin
                    if (&count_8) begin
                        count_8 <= 3'd0;
                        count_8_indication <= 1'b1;
                    end else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                        data_save <= {data_save[6:0], 1'b0};
