        if (rst) begin
            current_state <= IDLE;
        end else begin
            case (current_state)
                IDLE: begin
                    if (en == 1'b1)
                        current_state <= START;
                end
                START: begin
                    if (count_16_indication)
                        current_state <= DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        current_state <= STOP;
                end
                STOP: begin
                    if (count_16_indication)
                        current_state <= IDLE;
                end
                default: begin
                    current_state <= IDLE;
                end
            endcase
        end
    end

    always @(*) begin
        if (!rst) begin
            case (current_state)
                IDLE:  tx = 1'b1;
                START: tx = 1'b0;
                DATA:  tx = data_save[7];
                STOP:  tx = 1'b1;
            endcase
        end
    end

