module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;

    always @(posedge clk) begin
        if (rst) begin
            temp_en <= 0;
            delayed_en <= 0;
        end
        else begin
            temp_en <= en;
            delayed_en <= temp_en;
        end
    end

    reg [31:0] baud_count;

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 0;
            baud_tick <= 0;
        end
        else if (~|baud_division) begin
            baud_count <= 0;
            baud_tick <= 0;
        end
        else if (en & ~delayed_en) begin
            baud_count <= 1;
        end
        else if (baud_count == baud_division) begin
            baud_count <= 0;
            baud_tick <= 1;
        end
        else begin
            baud_count <= baud_count + 1'b1;
            baud_tick <= 0;
