            case (current_state)
                IDLE: begin
                    if (~rx)
                        next_state = START;
                end
                START: begin
                    if (count_16_indication & ~rx)
                        next_state = DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        next_state = STOP;
