// ---- file: UART.v0.v ----
module uart_top_design (
    input wire clk,
    input wire rst,
    input wire [1:0] address,
    input wire [31:0] write_data,
    input wire we,
    output wire tx,
    input wire rx,
    input wire re,
    output reg [7:0] read_data
);

    localparam BAUD_DATA = 2'd0;
    localparam ENABLE    = 2'd1;
    localparam TX_DATA   = 2'd2;
    localparam RX_DATA   = 2'd3;

    reg [31:0] baud_division;
    reg enable;
    reg [7:0] data_out;
    wire [7:0] data_in;

    always @(*) begin
        if (rst) begin
            baud_division = 32'd0;
            enable        = 1'b0;
            data_out      = 8'd0;
        end else begin
            case (address)
                BAUD_DATA: begin
                    if (we)
                        baud_division = write_data;
                end
                ENABLE: begin
                    if (we)
                        enable = write_data[0];
                end
                TX_DATA: begin
                    if (we)
                        data_out = write_data[7:0];
                end
                RX_DATA: begin
                    if (re)
                        read_data = data_in;
                end
            endcase
        end
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk           (clk),
        .rst           (rst),
        .baud_division (baud_division),
        .en            (enable),
        .baud_tick     (baud_tick)
    );

    uart_tx uut_tx (
        .clk         (clk),
        .rst         (rst),
        .baud_tick   (baud_tick),
        .ext_data_in (data_out),
        .en          (enable),
        .tx          (tx)
    );

    uart_rx uut_rx (
        .clk          (clk),
        .rst          (rst),
        .baud_tick    (baud_tick),
        .rx           (rx),
        .ext_data_out (data_in)
    );

endmodule


module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;
    reg [13:0] baud_count;

    wire div_nonzero = (baud_division != 32'd0);
    wire div_small   = (baud_division[31:14] == 18'd0);
    wire [13:0] div_lo = baud_division[13:0];

    always @(posedge clk) begin
        if (rst) begin
            temp_en    <= 1'b0;
            delayed_en <= 1'b0;
        end else begin
            temp_en    <= en;
            delayed_en <= temp_en;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 14'd0;
            baud_tick  <= 1'b0;
        end else begin
            if (div_nonzero) begin
                if (en && !delayed_en) begin
                    baud_count <= 14'd1;
                    baud_tick  <= baud_tick;
                end else if (div_small && (baud_count == div_lo)) begin
                    baud_count <= 14'd0;
                    baud_tick  <= 1'b1;
                end else begin
                    if (!div_small) begin
                        if (baud_count != 14'h3fff)
                            baud_count <= baud_count + 14'd1;
                    end else if (baud_count < div_lo) begin
                        baud_count <= baud_count + 14'd1;
                    end
                    baud_tick <= 1'b0;
                end
            end else begin
                baud_count <= 14'd0;
                baud_tick  <= 1'b0;
            end
        end
    end

endmodule


module uart_rx (
    input clk,
    input rst,
    input baud_tick,
    input rx,
    output wire [7:0] ext_data_out
);

    localparam IDLE  = 2'b00;
    localparam START = 2'b01;
    localparam DATA  = 2'b11;
    localparam STOP  = 2'b10;

    reg [3:0] count_16;
    reg count_16_indication;

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    reg [1:0] current_state;

    assign ext_data_out = data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'd0;
            count_16_indication <= 1'b0;
        end else begin
            if (baud_tick) begin
                if (current_state == START) begin
                    if (&count_16[2:0]) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else if ((current_state == DATA) || (current_state == STOP)) begin
                    if (&count_16) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else begin
                    count_16 <= 4'd0;
                    count_16_indication <= 1'b0;
                end
            end else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 3'd0;
            count_8_indication <= 1'b0;
            data_save <= 8'd0;
        end else begin
            if (current_state == DATA) begin
                if (baud_tick && (&count_16)) begin
                    data_save <= {data_save[6:0], rx};
                    if (&count_8) begin
                        count_8 <= 3'd0;
                        count_8_indication <= 1'b1;
                    end else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                    end
                end else begin
                    count_8_indication <= 1'b0;
                end
            end else begin
                count_8 <= 3'd0;
                count_8_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            current_state <= IDLE;
        end else begin
            case (current_state)
                IDLE: begin
                    if (rx == 1'b0)
                        current_state <= START;
                end
                START: begin
                    if (count_16_indication && (rx == 1'b0))
                        current_state <= DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        current_state <= STOP;
                end
                STOP: begin
                    if (count_16_indication && (rx == 1'b1))
                        current_state <= IDLE;
                end
                default: begin
                    current_state <= IDLE;
                end
            endcase
        end
    end

endmodule


module uart_tx (
    input wire clk,
    input wire rst,
    input wire baud_tick,
    input wire [7:0] ext_data_in,
    input wire en,
    output reg tx
);

    localparam IDLE  = 2'b00;
    localparam START = 2'b01;
    localparam DATA  = 2'b11;
    localparam STOP  = 2'b10;

    reg [3:0] count_16;
    reg count_16_indication;

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    reg [1:0] current_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'd0;
            count_16_indication <= 1'b0;
        end else begin
            if (baud_tick) begin
                if (current_state != IDLE) begin
                    if (&count_16) begin
                        count_16 <= 4'd0;
                        count_16_indication <= 1'b1;
                    end else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end else begin
                    count_16 <= 4'd0;
                    count_16_indication <= 1'b0;
                end
            end else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst) begin
            if (current_state == DATA) begin
                if (baud_tick && (&count_16)) begin
                    if (&count_8) begin
                        count_8 <= 3'd0;
                        count_8_indication <= 1'b1;
                    end else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                        data_save <= {data_save[6:0], 1'b0};
                    end
                end else begin
                    count_8_indication <= 1'b0;
                end
            end else begin
                count_8 <= 3'd0;
                count_8_indication <= 1'b0;
                data_save <= ext_data_in;
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            current_state <= IDLE;
        end else begin
            case (current_state)
                IDLE: begin
                    if (en == 1'b1)
                        current_state <= START;
                end
                START: begin
                    if (count_16_indication)
                        current_state <= DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        current_state <= STOP;
                end
                STOP: begin
                    if (count_16_indication)
                        current_state <= IDLE;
                end
                default: begin
                    current_state <= IDLE;
                end
            endcase
        end
    end

    always @(*) begin
        if (!rst) begin
            case (current_state)
                IDLE:  tx = 1'b1;
                START: tx = 1'b0;
                DATA:  tx = data_save[7];
                STOP:  tx = 1'b1;
            endcase
        end
    end

endmodule

