// ---- file: UART.v0.v ----
module uart_top_design (
    input wire clk,
    input wire rst,
    input wire [1:0] address,
    input wire [31:0] write_data,
    input wire we,
    output wire tx,
    input wire rx,
    input wire re,
    output reg [7:0] read_data
);

    reg [31:0] baud_division;
    reg enable;
    reg [7:0] data_out;
    wire [7:0] data_in;

    always @(*) begin
        if (rst) begin
            baud_division <= 0;
            enable <= 0;
            data_out <= 0;
        end
        else begin
            case (address)
                2'd0: begin
                    if (we)
                        baud_division <= write_data;
                end
                2'd1: begin
                    if (we)
                        enable <= write_data[0];
                end
                2'd2: begin
                    if (we)
                        data_out <= write_data[7:0];
                end
                2'd3: begin
                    if (re)
                        read_data <= data_in;
                end
            endcase
        end
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk (clk),
        .rst (rst),
        .baud_division (baud_division),
        .en (enable),
        .baud_tick (baud_tick)
    );

    uart_tx uut_tx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .ext_data_in (data_out),
        .en (enable),
        .tx (tx)
    );

    uart_rx uut_rx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .rx (rx),
        .ext_data_out (data_in)
    );

endmodule


module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;

    always @(posedge clk) begin
        if (rst) begin
            temp_en <= 0;
            delayed_en <= 0;
        end
        else begin
            temp_en <= en;
            delayed_en <= temp_en;
        end
    end

    reg [31:0] baud_count;

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 0;
            baud_tick <= 0;
        end
        else if (|baud_division) begin
            if (en & ~delayed_en) begin
                baud_count <= 1;
            end
            else if (baud_count == baud_division) begin
                baud_count <= 0;
                baud_tick <= 1;
            end
            else begin
                baud_count <= baud_count + 1;
                baud_tick <= 0;
            end
        end
        else begin
            baud_count <= 0;
            baud_tick <= 0;
        end
    end

endmodule


module uart_rx (
    input clk,
    input rst,
    input baud_tick,
    input rx,
    output reg [7:0] ext_data_out
);

    reg [3:0] count_16;
    reg count_16_indication;
    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] current_state, next_state;

    wire cnt16_at7 = (count_16 == 4'd7);
    wire cnt16_at15 = &count_16;
    wire cnt8_at7;

    always @(posedge clk) begin
        if (rst) begin
