                    if (we)
                        baud_division = write_data;
                end
                ENABLE: begin
                    if (we)
                        enable = write_data[0];
                end
                TX_DATA: begin
                    if (we)
                        data_out = write_data[7:0];
                end
                RX_DATA: begin
                    if (re)
                        read_data = data_in;
                end
            endcase
        end
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk           (clk),
        .rst           (rst),
        .baud_division (baud_division),
        .en            (enable),
        .baud_tick     (baud_tick)
    );

    uart_tx uut_tx (
        .clk         (clk),
        .rst         (rst),
        .baud_tick   (baud_tick),
        .ext_data_in (data_out),
        .en          (enable),
        .tx          (tx)
    );

    uart_rx uut_rx (
        .clk          (clk),
        .rst          (rst),
        .baud_tick    (baud_tick),
        .rx           (rx),
        .ext_data_out (data_in)
    );

endmodule


module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;
    reg [13:0] baud_count;

    wire div_nonzero = (baud_division != 32'd0);
    wire div_small   = (baud_division[31:14] == 18'd0);
    wire [13:0] div_lo = baud_division[13:0];

    always @(posedge clk) begin
        if (rst) begin
            temp_en    <= 1'b0;
            delayed_en <= 1'b0;
        end else begin
            temp_en    <= en;
            delayed_en <= temp_en;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 14'd0;
            baud_tick  <= 1'b0;
        end else begin
            if (div_nonzero) begin
                if (en && !delayed_en) begin
                    baud_count <= 14'd1;
                    baud_tick  <= baud_tick;
                end else if (div_small && (baud_count == div_lo)) begin
                    baud_count <= 14'd0;
                    baud_tick  <= 1'b1;
                end else begin
                    if (!div_small) begin
                        if (baud_count != 14'h3fff)
                            baud_count <= baud_count + 14'd1;
                    end else if (baud_count < div_lo) begin
                        baud_count <= baud_count + 14'd1;
                    end
                    baud_tick <= 1'b0;
                end
            end else begin
                baud_count <= 14'd0;
                baud_tick  <= 1'b0;
            end
        end
    end

