    rx = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    re = _rnd[0];
    rst = (($urandom % 32) == 0) ? 1'b1 : 1'b0;
  endtask
  initial begin
