                        count_16_indication <= 1'b1;
                    end
                    else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end
                else begin
                    count_16 <= 4'b0;
                    count_16_indication <= 1'b0;
                end
