    reg [3:0] count_16;
    reg count_16_indication;
    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else begin
            if (baud_tick) begin
                if (current_state == START) begin
                    if (count_16 == 4'd7) begin
                        count_16 <= 0;
                        count_16_indication <= 1;
                    end
                    else begin
                        count_16 <= count_16 + 1;
                        count_16_indication <= 0;
                    end
                end
                else if (current_state == DATA || current_state == STOP) begin
                    if (&count_16) begin
                        count_16 <= 0;
                        count_16_indication <= 1;
                    end
                    else begin
                        count_16 <= count_16 + 1;
                        count_16_indication <= 0;
                    end
                end
                else begin
                    count_16 <= 0;
                    count_16_indication <= 0;
                end
            end
            else begin
                count_16_indication <= 0;
            end
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
        else if (current_state == DATA) begin
            if (baud_tick && &count_16) begin
                if (&count_8) begin
                    count_8 <= 0;
                    count_8_indication <= 1;
                end
                else begin
                    count_8 <= count_8 + 1;
                    count_8_indication <= 0;
                end
            end
            else begin
                count_8_indication <= 0;
            end
        end
        else begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
    end

    always @(posedge clk) begin
        if (rst)
            data_save <= 0;
        else if (current_state == DATA && baud_tick && &count_16)
            data_save <= {data_save[6:0], rx};
    end

    always @(posedge clk) begin
        if (rst)
            ext_data_out <= 0;
        else
            ext_data_out <= data_save;
    end

    always @(posedge clk) begin
        if (rst)
            current_state <= 0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        if (rst) begin
            next_state = 0;
        end
        else begin
            case (current_state)
                IDLE: begin
                    if (!rx)
                        next_state = START;
                end
                START: begin
                    if (count_16_indication && !rx)
                        next_state = DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    if (count_16_indication && rx)
                        next_state = IDLE;
                end
                default: next_state = IDLE;
            endcase
        end
    end

endmodule


module uart_tx (
    input wire clk,
    input wire rst,
    input wire baud_tick,
    input wire [7:0] ext_data_in,
    input wire en,
    output reg tx
);

    reg [3:0] count_16;
    reg count_16_indication;
    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else begin
            if (baud_tick) begin
                if (current_state != IDLE) begin
                    if (&count_16) begin
                        count_16 <= 0;
                        count_16_indication <= 1;
                    end
                    else begin
                        count_16 <= count_16 + 1;
                        count_16_indication <= 0;
                    end
                end
                else begin
                    count_16 <= 0;
                    count_16_indication <= 0;
                end
            end
            else begin
                count_16_indication <= 0;
            end
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
        else if (current_state == DATA) begin
            if (baud_tick && &count_16) begin
                if (&count_8) begin
                    count_8 <= 0;
                    count_8_indication <= 1;
                end
                else begin
                    count_8 <= count_8 + 1;
                    count_8_indication <= 0;
                end
            end
            else begin
                count_8_indication <= 0;
            end
        end
        else begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
    end

    always @(posedge clk) begin
        if (rst)
            data_save <= 0;
        else if (current_state == DATA) begin
            if (baud_tick && &count_16 && !(&count_8))
                data_save <= {data_save[6:0], 1'b0};
        end
        else if (current_state != IDLE)
            data_save <= ext_data_in;
    end

    always @(posedge clk) begin
        if (rst)
            current_state <= 0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        if (rst) begin
            next_state = 0;
        end
        else begin
            case (current_state)
                IDLE: begin
                    tx = 1;
                    if (en)
                        next_state = START;
                end
                START: begin
                    tx = 0;
                    if (count_16_indication)
                        next_state = DATA;
                end
                DATA: begin
                    tx = data_save[7];
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    tx = 1;
                    if (count_16_indication)
                        next_state = IDLE;
                end
                default: next_state = IDLE;
            endcase
        end
    end

