// ---- file: tv80.v0.v ----
module tv80_alu (/*AUTOARG*/
  // Outputs
  Q, F_Out, 
  // Inputs
  Arith16, Z16, ALU_Op, IR, ISet, BusA, BusB, F_In
  );

  parameter		Mode   = 0;
  parameter		Flag_C = 0;
  parameter		Flag_N = 1;
  parameter		Flag_P = 2;
  parameter		Flag_X = 3;
  parameter		Flag_H = 4;
  parameter		Flag_Y = 5;
  parameter		Flag_Z = 6;
  parameter		Flag_S = 7;

  input 		Arith16;
  input 		Z16;
  input [3:0]           ALU_Op ;
  input [5:0]           IR;
  input [1:0]           ISet;
  input [7:0]           BusA;
  input [7:0]           BusB;
  input [7:0]           F_In;
  output [7:0]          Q;
  output [7:0]          F_Out;
  reg [7:0]             Q;
  reg [7:0]             F_Out;

  function [4:0] AddSub4;
    input [3:0] A;
    input [3:0] B;
    input Sub;
    input Carry_In;
    begin
      AddSub4 = { 1'b0, A } + { 1'b0, (B ^ {4{Sub}}) } + Carry_In;
    end
  endfunction

  function [3:0] AddSub3;
    input [2:0] A;
    input [2:0] B;
    input Sub;
    input Carry_In;
    begin
      AddSub3 = { 1'b0, A } + { 1'b0, (B ^ {3{Sub}}) } + Carry_In;
    end
  endfunction

  function [1:0] AddSub1;
    input A;
    input B;
    input Sub;
    input Carry_In;
    begin
      AddSub1 = { 1'b0, A } + { 1'b0, (B ^ Sub) } + Carry_In;
    end
  endfunction

  reg UseCarry;
  reg Carry7_v;
  reg OverFlow_v;
  reg HalfCarry_v;
  reg Carry_v;
  reg [7:0] Q_v;

  reg [7:0] BitMask;

  wire        DAA_N       = F_In[Flag_N];
  wire        DAA_NotN    = ~F_In[Flag_N];
  wire        DAA_LowGt9  = (BusA[3:0] > 4'd9);
  wire        DAA_LowGt5  = (BusA[3:0] > 4'd5);
  wire        DAA_Adj6    = DAA_LowGt9 | F_In[Flag_H];
  wire        DAA_HiGt9   = (BusA[7:4] > 4'd9) |
                            ((BusA[7:4] == 4'd9) & DAA_LowGt9);
  wire        DAA_Add60   = DAA_HiGt9 | F_In[Flag_C];

  wire [7:0]  DAA_SubLow  = BusA + (DAA_Adj6 ? 8'd250 : 8'd0);
  wire        DAA_Sub60   = (BusA > 8'd153) | F_In[Flag_C];

  wire        DAA_Corr7   = DAA_N    & DAA_Sub60;
  wire        DAA_Corr6   = DAA_NotN & DAA_Add60;
  wire        DAA_Corr5   = DAA_Corr7 | DAA_Corr6;
  wire        DAA_Corr21  = DAA_NotN & DAA_Adj6;

  wire [8:0]  DAA_Pre     = DAA_N ? {1'b0, DAA_SubLow} : {1'b0, BusA};
  wire [8:0]  DAA_Corr    = {1'b0, DAA_Corr7, DAA_Corr6, DAA_Corr5,
                              2'b00, DAA_Corr21, DAA_Corr21, 1'b0};
  wire [8:0]  DAA_Q_w     = DAA_Pre + DAA_Corr;
  wire        DAA_H_w     = (DAA_N & F_In[Flag_H] & ~DAA_LowGt5) |
                            (DAA_NotN & DAA_LowGt9);

  always @*
    begin
      case (IR[5:3])
        3'b000 : BitMask = 8'b00000001;
        3'b001 : BitMask = 8'b00000010;
        3'b010 : BitMask = 8'b00000100; 
        3'b011 : BitMask = 8'b00001000; 
        3'b100 : BitMask = 8'b00010000; 
        3'b101 : BitMask = 8'b00100000; 
        3'b110 : BitMask = 8'b01000000; 
        default: BitMask = 8'b10000000; 
      endcase

      UseCarry = (~ALU_Op[2]) & ALU_Op[0];
      { HalfCarry_v, Q_v[3:0] } = AddSub4(BusA[3:0], BusB[3:0], ALU_Op[1], ALU_Op[1] ^ (UseCarry & F_In[Flag_C]) );
      { Carry7_v, Q_v[6:4]  } = AddSub3(BusA[6:4], BusB[6:4], ALU_Op[1], HalfCarry_v);
      { Carry_v, Q_v[7] } = AddSub1(BusA[7], BusB[7], ALU_Op[1], Carry7_v);
      OverFlow_v = Carry_v ^ Carry7_v;
    end

  reg [7:0] Q_t;
  reg       ArithFlag_v;
  reg       CpFlag_v;

  always @*
    begin
      Q_t = 8'hxx;
      ArithFlag_v = 1'b0;
      CpFlag_v = 1'b0;

      F_Out = F_In;
      casez (ALU_Op)
	4'b0??? :
          begin
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_C] = 1'b0;

            ArithFlag_v = (~ALU_Op[2]) | (ALU_Op[1] & ALU_Op[0]);
            CpFlag_v    = ALU_Op[2] & ALU_Op[1] & ALU_Op[0];

            if (ArithFlag_v)
              begin
                Q_t = Q_v;
                F_Out[Flag_N] = ALU_Op[1];
                F_Out[Flag_C] = Carry_v ^ ALU_Op[1];
                F_Out[Flag_H] = HalfCarry_v ^ ALU_Op[1];
                F_Out[Flag_P] = OverFlow_v;
              end
            else
              begin
                case (ALU_Op[1:0])
                  2'b00:
                    begin
                      Q_t = BusA & BusB;
                      F_Out[Flag_H] = 1'b1;
                    end
                  2'b01:
                    begin
                      Q_t = BusA ^ BusB;
                      F_Out[Flag_H] = 1'b0;
                    end
                  default:
                    begin
                      Q_t = BusA | BusB;
                      F_Out[Flag_H] = 1'b0;
                    end
                endcase
                F_Out[Flag_P] = ~(^Q_t);
              end

	    if (CpFlag_v) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end 
            else 
              begin
		F_Out[Flag_X] = Q_t[3];
		F_Out[Flag_Y] = Q_t[5];
	      end

	    F_Out[Flag_Z] = (~|Q_t) & ((~Z16) | F_In[Flag_Z]);
	    F_Out[Flag_S] = Q_t[7];

	    if (Arith16 == 1'b1 ) 
              begin
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
		F_Out[Flag_P] = F_In[Flag_P];
	      end
          end

	4'b1100 :
          begin
	    F_Out[Flag_H] = DAA_H_w;
	    F_Out[Flag_C] = F_In[Flag_C] | DAA_Q_w[8];
	    F_Out[Flag_X] = DAA_Q_w[3];
	    F_Out[Flag_Y] = DAA_Q_w[5];
	    Q_t = DAA_Q_w[7:0];
	    F_Out[Flag_Z] = ~|DAA_Q_w[7:0];
	    F_Out[Flag_S] = DAA_Q_w[7];
	    F_Out[Flag_P] = ~ (^DAA_Q_w);
          end

	4'b1101, 4'b1110 :
          begin
	    Q_t = {BusA[7:4], (ALU_Op[0] ? BusB[7:4] : BusB[3:0])};
	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_Z] = ~|Q_t;
	    F_Out[Flag_S] = Q_t[7];
            F_Out[Flag_P] = ~(^Q_t);
          end

	4'b1001 :
          begin
	    Q_t[7:0] = BusB & BitMask;
	    F_Out[Flag_S] = Q_t[7];
	    F_Out[Flag_Z] = ~|Q_t;
	    F_Out[Flag_P] = ~|Q_t;
	    F_Out[Flag_H] = 1'b1;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = 1'b0;
	    F_Out[Flag_Y] = 1'b0;
	    if (IR[2:0] != 3'b110 ) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end
          end

	4'b101? :
	  Q_t[7:0] = (BusB & ~BitMask) | ({8{~ALU_Op[0]}} & BitMask);

	4'b1000 :
          begin
	    if ((Mode == 3) && (IR[5:3] == 3'b110))
              begin
		Q_t[7:4] = BusA[3:0];
		Q_t[3:0] = BusA[7:4];
		F_Out[Flag_C] = 1'b0;
              end
            else if (IR[3] == 1'b0)
              begin
		Q_t[7:1] = BusA[6:0];
		F_Out[Flag_C] = BusA[7];
		case (IR[5:4])
		  2'b00: Q_t[0] = BusA[7];
		  2'b01: Q_t[0] = F_In[Flag_C];
		  2'b10: Q_t[0] = 1'b0;
		  default: Q_t[0] = 1'b1;
		endcase
              end
            else
              begin
		Q_t[6:0] = BusA[7:1];
		F_Out[Flag_C] = BusA[0];
		case (IR[5:4])
		  2'b00: Q_t[7] = BusA[0];
		  2'b01: Q_t[7] = F_In[Flag_C];
		  2'b10: Q_t[7] = BusA[7];
		  default: Q_t[7] = 1'b0;
		endcase
              end

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_S] = Q_t[7];
	    F_Out[Flag_Z] = ~|Q_t;
            F_Out[Flag_P] = ~(^Q_t);

	    if (~|ISet) 
              begin
		F_Out[Flag_P] = F_In[Flag_P];
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
	      end
          end

	default :
	  ;

      endcase

      Q = Q_t;
    end

endmodule

state.rtl_b:
// ---- file: tv80.v0.v ----
module tv80_alu (/*AUTOARG*/
  // Outputs
  Q, F_Out, 
  // Inputs
  Arith16, Z16, ALU_Op, IR, ISet, BusA, BusB, F_In
  );

  parameter		Mode   = 0;
  parameter		Flag_C = 0;
  parameter		Flag_N = 1;
  parameter		Flag_P = 2;
  parameter		Flag_X = 3;
  parameter		Flag_H = 4;
  parameter		Flag_Y = 5;
  parameter		Flag_Z = 6;
  parameter		Flag_S = 7;

  input 		Arith16;
  input 		Z16;
  input [3:0]           ALU_Op ;
  input [5:0]           IR;
  input [1:0]           ISet;
  input [7:0]           BusA;
  input [7:0]           BusB;
  input [7:0]           F_In;
  output [7:0]          Q;
  output [7:0]          F_Out;
  reg [7:0]             Q;
  reg [7:0]             F_Out;

  reg UseCarry;
  reg Carry7_v;
  reg OverFlow_v;
  reg HalfCarry_v;
  reg Carry_v;
  reg [7:0] Q_v;
  reg [7:0] Bmod_v;
  reg [7:0] Prop_v;
  reg [8:0] Cchain_v;

  wire [7:0] BitMask;
  assign BitMask[0] = ~IR[5] & ~IR[4] & ~IR[3];
  assign BitMask[1] = ~IR[5] & ~IR[4] &  IR[3];
  assign BitMask[2] = ~IR[5] &  IR[4] & ~IR[3];
  assign BitMask[3] = ~IR[5] &  IR[4] &  IR[3];
  assign BitMask[4] =  IR[5] & ~IR[4] & ~IR[3];
  assign BitMask[5] =  IR[5] & ~IR[4] &  IR[3];
  assign BitMask[6] =  IR[5] &  IR[4] & ~IR[3];
  assign BitMask[7] =  IR[5] &  IR[4] &  IR[3];

  always @(/*AUTOSENSE*/ALU_Op or BusA or BusB or F_In)
    begin
      UseCarry = ~ ALU_Op[2] && ALU_Op[0];
      Bmod_v = BusB ^ {8{ALU_Op[1]}};
      Prop_v = BusA ^ Bmod_v;

      Cchain_v[0] = ALU_Op[1] ^ (UseCarry && F_In[Flag_C]);

      Q_v[0] = Prop_v[0] ^ Cchain_v[0];
      Cchain_v[1] = (BusA[0] & Bmod_v[0]) | (Prop_v[0] & Cchain_v[0]);

      Q_v[1] = Prop_v[1] ^ Cchain_v[1];
      Cchain_v[2] = (BusA[1] & Bmod_v[1]) | (Prop_v[1] & Cchain_v[1]);

      Q_v[2] = Prop_v[2] ^ Cchain_v[2];
      Cchain_v[3] = (BusA[2] & Bmod_v[2]) | (Prop_v[2] & Cchain_v[2]);

      Q_v[3] = Prop_v[3] ^ Cchain_v[3];
      Cchain_v[4] = (BusA[3] & Bmod_v[3]) | (Prop_v[3] & Cchain_v[3]);

      Q_v[4] = Prop_v[4] ^ Cchain_v[4];
      Cchain_v[5] = (BusA[4] & Bmod_v[4]) | (Prop_v[4] & Cchain_v[4]);

      Q_v[5] = Prop_v[5] ^ Cchain_v[5];
      Cchain_v[6] = (BusA[5] & Bmod_v[5]) | (Prop_v[5] & Cchain_v[5]);

      Q_v[6] = Prop_v[6] ^ Cchain_v[6];
      Cchain_v[7] = (BusA[6] & Bmod_v[6]) | (Prop_v[6] & Cchain_v[6]);

      Q_v[7] = Prop_v[7] ^ Cchain_v[7];
      Cchain_v[8] = (BusA[7] & Bmod_v[7]) | (Prop_v[7] & Cchain_v[7]);

      HalfCarry_v = Cchain_v[4];
      Carry7_v = Cchain_v[7];
      Carry_v = Cchain_v[8];
      OverFlow_v = Carry_v ^ Carry7_v;
    end

  reg [7:0] Q_t;
  reg [8:0] DAA_Q;

  always @ (/*AUTOSENSE*/ALU_Op or Arith16 or BitMask or BusA or BusB
	    or Carry_v or F_In or HalfCarry_v or IR or ISet
	    or OverFlow_v or Q_v or Z16)
    begin
      Q_t = 8'hxx;
      DAA_Q = {9{1'bx}};

      F_Out = F_In;
      case (ALU_Op)
	4'b0000, 4'b0001,  4'b0010, 4'b0011, 4'b0100, 4'b0101, 4'b0110, 4'b0111 :
          begin
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_C] = 1'b0;

	    case (ALU_Op[2:0])
	      3'b000, 3'b001 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_C] = Carry_v;
		  F_Out[Flag_H] = HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end
	      3'b010, 3'b011, 3'b111 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_N] = 1'b1;
		  F_Out[Flag_C] = ~ Carry_v;
		  F_Out[Flag_H] = ~ HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end
	      3'b100 :
                begin
		  Q_t[7:0] = BusA & BusB;
		  F_Out[Flag_H] = 1'b1;
                end
	      3'b101 :
                begin
		  Q_t[7:0] = BusA ^ BusB;
		  F_Out[Flag_H] = 1'b0;
                end
	      default :
                begin
		  Q_t[7:0] = BusA | BusB;
		  F_Out[Flag_H] = 1'b0;
                end
	    endcase

	    if (ALU_Op[2:0] == 3'b111 ) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end 
            else 
              begin
		F_Out[Flag_X] = Q_t[3];
		F_Out[Flag_Y] = Q_t[5];
	      end

	    if (Q_t[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
		if (Z16 == 1'b1 ) 
                  begin
		    F_Out[Flag_Z] = F_In[Flag_Z];
		  end
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
	      end

	    F_Out[Flag_S] = Q_t[7];
	    case (ALU_Op[2:0])
	      3'b000, 3'b001, 3'b010, 3'b011, 3'b111 :
                ;
	      default :
	        F_Out[Flag_P] = ~(^Q_t);
	    endcase

	    if (Arith16 == 1'b1 ) 
              begin
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
		F_Out[Flag_P] = F_In[Flag_P];
	      end
          end

	4'b1100 :
          begin
	    F_Out[Flag_H] = F_In[Flag_H];
	    F_Out[Flag_C] = F_In[Flag_C];
	    DAA_Q[7:0] = BusA;
	    DAA_Q[8] = 1'b0;
	    if (F_In[Flag_N] == 1'b0 ) 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1 ) 
                  begin
		    if ((DAA_Q[3:0] > 9) ) 
                      begin
			F_Out[Flag_H] = 1'b1;
		      end 
                    else 
                      begin
			F_Out[Flag_H] = 1'b0;
		      end
		    DAA_Q = DAA_Q + 6;
		  end
		if (DAA_Q[8:4] > 9 || F_In[Flag_C] == 1'b1 ) 
                  begin
		    DAA_Q = DAA_Q + 96;
		  end
	      end 
            else 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1 ) 
                  begin
		    if (DAA_Q[3:0] > 5 ) 
                      begin
			F_Out[Flag_H] = 1'b0;
		      end
		    DAA_Q[7:0] = DAA_Q[7:0] - 6;
		  end
		if (BusA > 153 || F_In[Flag_C] == 1'b1 ) 
                  begin
		    DAA_Q = DAA_Q - 352;
		  end
	      end

	    F_Out[Flag_X] = DAA_Q[3];
	    F_Out[Flag_Y] = DAA_Q[5];
	    F_Out[Flag_C] = F_In[Flag_C] || DAA_Q[8];
	    Q_t = DAA_Q[7:0];

	    if (DAA_Q[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
	      end

	    F_Out[Flag_S] = DAA_Q[7];
	    F_Out[Flag_P] = ~ (^DAA_Q);
          end

	4'b1101, 4'b1110 :
          begin
	    Q_t[7:4] = BusA[7:4];
	    if (ALU_Op[0] == 1'b1 ) 
              begin
		Q_t[3:0] = BusB[7:4];
	      end 
            else 
              begin
		Q_t[3:0] = BusB[3:0];
	      end
	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    if (Q_t[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
	      end
	    F_Out[Flag_S] = Q_t[7];
            F_Out[Flag_P] = ~(^Q_t);
          end

	4'b1001 :
          begin
	    Q_t[7:0] = BusB & BitMask;
	    F_Out[Flag_S] = Q_t[7];
	    if (Q_t[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
		F_Out[Flag_P] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
		F_Out[Flag_P] = 1'b0;
	      end
	    F_Out[Flag_H] = 1'b1;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = 1'b0;
	    F_Out[Flag_Y] = 1'b0;
	    if (IR[2:0] != 3'b110 ) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end
          end

	4'b1010 :
	  Q_t[7:0] = BusB | BitMask;

	4'b1011 :
	  Q_t[7:0] = BusB & ~ BitMask;

	4'b1000 :
          begin
	    case (IR[5:3])
	      3'b000 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = BusA[7];
		  F_Out[Flag_C] = BusA[7];
                end
	      3'b010 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[7];
                end
	      3'b001 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[0];
		  F_Out[Flag_C] = BusA[0];
                end
	      3'b011 :
                begin                        
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[0];
                end
	      3'b100 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = 1'b0;
		  F_Out[Flag_C] = BusA[7];
                end
	      3'b110 :
                begin
		  if (Mode == 3 ) 
                    begin
		      Q_t[7:4] = BusA[3:0];
		      Q_t[3:0] = BusA[7:4];
		      F_Out[Flag_C] = 1'b0;                            
		    end 
                  else 
                    begin
		      Q_t[7:1] = BusA[6:0];
		      Q_t[0] = 1'b1;
		      F_Out[Flag_C] = BusA[7];
		    end
                end
	      3'b101 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[7];
		  F_Out[Flag_C] = BusA[0];
                end
	      default :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = 1'b0;
		  F_Out[Flag_C] = BusA[0];
                end
	    endcase

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_S] = Q_t[7];
	    if (Q_t[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
	      end
            F_Out[Flag_P] = ~(^Q_t);

	    if (ISet == 2'b00 ) 
              begin
		F_Out[Flag_P] = F_In[Flag_P];
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
	      end
          end

	default :
	  ;
      endcase

      Q = Q_t;
    end

endmodule

