`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_tv80;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  PT_WARMUP_CYCLES = 16;
  localparam int  RESET_CYCLES = 8;
  logic Arith16;
  logic Z16;
  logic [3:0] ALU_Op;
  logic [5:0] IR;
  logic [1:0] ISet;
  logic [7:0] BusA;
  logic [7:0] BusB;
  logic [7:0] F_In;
  logic [7:0] Q;
  logic [7:0] F_Out;
  logic [131071:0] _rnd;

  tv80_alu tv80_alu0 (
    .Arith16(Arith16),
    .Z16(Z16),
    .ALU_Op(ALU_Op),
    .IR(IR),
    .ISet(ISet),
    .BusA(BusA),
    .BusB(BusB),
    .F_In(F_In),
    .Q(Q),
    .F_Out(F_Out)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    Arith16 = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    Z16 = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    ALU_Op = _rnd[3:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    IR = _rnd[5:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    ISet = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    BusA = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    BusB = _rnd[7:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    F_In = _rnd[7:0];
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    Arith16 = '0;
    Z16 = '0;
    ALU_Op = '0;
    IR = '0;
    ISet = '0;
    BusA = '0;
    BusB = '0;
    F_In = '0;

    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_tv80);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin drive_inputs(); #(SETTLE_NS); end
    $dumpoff;
    $finish;
  end
  initial begin #((N_PT + 200) * SETTLE_NS * 4); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.rtl_a:
// ---- file: controller.v0.v ----
module control_unit
(
	output reg [ 2:0] sbox_sel,
	output reg [ 1:0] rk_sel,
	output reg [ 1:0] key_out_sel,
	output reg [ 1:0] col_sel,
	output reg [ 3:0] key_en,
	output reg [ 3:0] col_en,
	output     [ 3:0] round,
	output reg bypass_rk,
	output reg bypass_key_en,
	output reg key_sel,
	output reg iv_cnt_en,
	output reg iv_cnt_sel,
	output reg key_derivation_en,
	output end_comp,
	output key_init,
	output key_gen,
	output mode_ctr,
	output mode_cbc,
	output last_round,
	output encrypt_decrypt,	
	input [1:0] operation_mode,
	input [1:0] aes_mode,
	input start,
	input disable_core,
	input clk,
	input rst_n
);

//=============================================================================
// Operation Modes
//=============================================================================
localparam ENCRYPTION     = 2'b00;
localparam KEY_DERIVATION = 2'b01;
localparam DECRYPTION     = 2'b10;
localparam DECRYP_W_DERIV = 2'b11;

//=============================================================================
// AES Modes
//=============================================================================
localparam CBC = 2'b01;
localparam CTR = 2'b10;

//=============================================================================
// Datapath Select Values
//=============================================================================
localparam COL_0      = 3'b000;
localparam G_FUNCTION = 3'b100;

localparam COL        = 2'b00;
localparam MIXCOL_IN  = 2'b01;
localparam MIXCOL_OUT = 2'b10;

localparam KEY_0 = 2'b00;

localparam SHIFT_ROWS = 2'b00;
localparam ADD_RK_OUT = 2'b01;
localparam INPUT      = 2'b10;

localparam KEY_HOST = 1'b0;
localparam KEY_OUT  = 1'b1;

localparam KEY_DIS  = 4'b0000;
localparam EN_KEY_0 = 4'b0001;
localparam EN_KEY_1 = 4'b0010;
localparam EN_KEY_2 = 4'b0100;
localparam EN_KEY_3 = 4'b1000;

localparam COL_DIS = 4'b0000;
localparam COL_ALL = 4'b1111;

localparam IV_CNT = 1'b1;
localparam IV_BUS = 1'b0;

localparam ENABLE  = 1'b1;
localparam DISABLE = 1'b0;

localparam INITIAL_ROUND = 4'd0;

//=============================================================================
// FSM STATES
// Encoding:
//   00xx : special states
//   01cc : ROUND0 column cc
//   10cc : ROUND column cc
//   11kk : GEN_KEY kk
//=============================================================================
localparam IDLE        = 4'b0000;
localparam ROUND_KEY0  = 4'b0001;
localparam READY       = 4'b0010;
localparam NOP         = 4'b0011;

localparam ROUND0_COL0 = 4'b0100;
localparam ROUND0_COL3 = 4'b0111;

localparam ROUND_COL0  = 4'b1000;
localparam ROUND_COL3  = 4'b1011;

localparam GEN_KEY0    = 4'b1100;
localparam GEN_KEY3    = 4'b1111;

reg [3:0] state, next_state;
reg [3:0] rd_count;

wire enc_dec;
wire op_key_derivation;
wire first_round;
wire not_enc_dec;
wire not_last_round;
wire last_round_and_enc_dec;
wire last_round_and_mode_ctr;
wire last_round_special_case;

wire grp_r0;
wire grp_rc;
wire grp_gen;
wire grp_col;

wire col0;
wire col1;
wire col2;
wire col3;
wire [3:0] col_onehot;
wire [3:0] col_next_onehot;

wire st_idle;
wire st_rkey;
wire st_ready;
wire st_gen0;
wire st_gen3;
wire rd_count_en;

assign mode_ctr = aes_mode[1] & ~aes_mode[0];
assign mode_cbc = ~aes_mode[1] & aes_mode[0];

assign grp_r0  = ~state[3] &  state[2];
assign grp_rc  =  state[3] & ~state[2];
assign grp_gen =  state[3] &  state[2];
assign grp_col =  state[3] ^  state[2];

assign col0 = ~state[1] & ~state[0];
assign col1 = ~state[1] &  state[0];
assign col2 =  state[1] & ~state[0];
assign col3 =  state[1] &  state[0];

assign col_onehot      = {col3, col2, col1, col0};
assign col_next_onehot = {col2, col1, col0, 1'b0};

assign st_idle  = ~state[3] & ~state[2] & col0;
assign st_rkey  = ~state[3] & ~state[2] & col1;
assign st_ready = ~state[3] & ~state[2] & col2;
assign st_gen0  =  grp_gen & col0;
assign st_gen3  =  grp_gen & col3;

assign encrypt_decrypt = mode_ctr | ~operation_mode[1] | grp_gen;
assign enc_dec = encrypt_decrypt;

assign op_key_derivation = ~mode_ctr & ~operation_mode[1] & operation_mode[0];

assign key_gen = st_rkey;
assign key_init = start;

assign not_enc_dec = ~enc_dec;
assign not_last_round = ~last_round;
assign last_round_and_enc_dec = last_round & enc_dec;
assign last_round_and_mode_ctr = last_round & mode_ctr;
assign last_round_special_case = (last_round & mode_cbc & not_enc_dec) | last_round_and_mode_ctr;

assign rd_count_en = st_rkey | st_gen0;

// State Flops Definition
always @(posedge clk, negedge rst_n)
begin
	if(!rst_n)
		state <= IDLE;
	else if(disable_core)
		state <= IDLE;
	else
		state <= next_state;
end

// Next State Logic
always @(*)
begin
	next_state = state;

	case (state[3:2])
		2'b00: begin
			case (state[1:0])
				2'b00: begin // IDLE
					if(!start)
						next_state = IDLE;
					else if(mode_ctr)
						next_state = ROUND0_COL0;
					else begin
						case(operation_mode)
							ENCRYPTION     : next_state = ROUND0_COL0;
							DECRYPTION     : next_state = ROUND0_COL3;
							KEY_DERIVATION : next_state = GEN_KEY0;
							DECRYP_W_DERIV : next_state = GEN_KEY0;
							default        : next_state = IDLE;
						endcase
					end
				end

				2'b01: begin // ROUND_KEY0
					if(!first_round)
						next_state = last_round ? READY : NOP;
					else
						next_state = enc_dec ? ROUND_COL0 : ROUND_COL3;
				end

				2'b10: begin // READY
					next_state = IDLE;
				end

				2'b11: begin // NOP
					next_state = enc_dec ? ROUND_COL0 : ROUND_COL3;
				end
			endcase
		end

		2'b01: begin // ROUND0_COL*
			if(enc_dec)
				next_state = col3 ? ROUND_KEY0 : (state + 4'd1);
			else
				next_state = col0 ? ROUND_KEY0 : (state - 4'd1);
		end

		2'b10: begin // ROUND_COL*
			if(enc_dec) begin
				if(col3)
					next_state = last_round ? READY : ROUND_KEY0;
				else
					next_state = state + 4'd1;
			end else begin
				next_state = col0 ? ROUND_KEY0 : (state - 4'd1);
			end
		end

		2'b11: begin // GEN_KEY*
			if(col3) begin
				if(last_round)
					next_state = op_key_derivation ? READY : ROUND0_COL3;
				else
					next_state = GEN_KEY0;
			end else begin
				next_state = state + 4'd1;
			end
		end
	endcase
end

// Output Logic
assign end_comp = st_ready ? ENABLE : DISABLE;

always @(*)
begin
	sbox_sel = COL_0;
	rk_sel = COL;
	bypass_rk = DISABLE;
	key_out_sel = KEY_0;
	col_sel = INPUT;
	key_sel = KEY_HOST;
	key_en = KEY_DIS;
	col_en = COL_DIS;
	iv_cnt_en = DISABLE;
	iv_cnt_sel = IV_BUS;
	bypass_key_en = DISABLE;
	key_derivation_en = DISABLE;

	if(st_rkey || st_gen0)
		sbox_sel = G_FUNCTION;
	else if(grp_col)
		sbox_sel = {1'b0, state[1:0]};

	if(grp_col)
		key_out_sel = state[1:0];

	if(grp_rc)
		rk_sel = last_round ? MIXCOL_IN : MIXCOL_OUT;

	bypass_rk = grp_r0 ? ENABLE : DISABLE;
	bypass_key_en = (grp_r0 || (grp_gen && !col0)) ? ENABLE : DISABLE;

	if(st_rkey || grp_rc || (grp_gen && !col0) || (grp_r0 && !col0 && not_enc_dec))
		key_sel = KEY_OUT;

	if(st_rkey) begin
		key_en = EN_KEY_0;
	end else if(grp_r0 && not_enc_dec) begin
		key_en = col0 ? KEY_DIS : col_onehot;
	end else if(grp_rc) begin
		key_en = enc_dec ? col_next_onehot : (col0 ? KEY_DIS : col_onehot);
	end else if(grp_gen) begin
		if(col1)
			key_en = EN_KEY_1 | EN_KEY_0;
		else if(col2)
			key_en = EN_KEY_2;
		else if(col3)
			key_en = EN_KEY_3;
	end

	if(grp_r0) begin
		if((enc_dec && col3) || (not_enc_dec && col0))
			col_sel = SHIFT_ROWS;
		else
			col_sel = ADD_RK_OUT;
	end else if(grp_rc) begin
		if(last_round_special_case)
			col_sel = INPUT;
		else if((enc_dec && col3 && not_last_round) ||
		        (not_enc_dec && col0 && not_last_round))
			col_sel = SHIFT_ROWS;
		else
			col_sel = ADD_RK_OUT;
	end

	if(grp_r0) begin
		if(enc_dec)
			col_en = col3 ? COL_ALL : col_onehot;
		else
			col_en = col0 ? COL_ALL : col_onehot;
	end else if(grp_rc) begin
		if(enc_dec) begin
			if(col3)
				col_en = last_round ? col_onehot : COL_ALL;
			else
				col_en = col_onehot;
		end else begin
			if(col0)
				col_en = last_round ? col_onehot : COL_ALL;
			else
				col_en = col_onehot;
		end
	end

	if(grp_rc && col3 && last_round_and_mode_ctr) begin
		iv_cnt_en = ENABLE;
		iv_cnt_sel = IV_CNT;
	end

	if(st_ready && op_key_derivation)
		key_derivation_en = ENABLE;
end

// Round Counter
always @(posedge clk, negedge rst_n)
begin
	if(!rst_n)
		rd_count <= INITIAL_ROUND;
	else if(st_idle || (st_gen3 && last_round))
		rd_count <= INITIAL_ROUND;
	else if(rd_count_en)
		rd_count <= rd_count + 1'b1;
end

assign round = rd_count;
assign first_round = ~(|rd_count);
assign last_round  = rd_count[3] & ~rd_count[2] & rd_count[1];

endmodule

state.rtl_b:
// ---- file: controller.v0.v ----
module control_unit
(
	output     [ 2:0] sbox_sel,
	output reg [ 1:0] rk_sel,
	output reg [ 1:0] key_out_sel,
	output reg [ 1:0] col_sel,
	output reg [ 3:0] key_en,
	output reg [ 3:0] col_en,
	output     [ 3:0] round,
	output bypass_rk,
	output reg bypass_key_en,
	output reg key_sel,
	output reg iv_cnt_en,
	output reg iv_cnt_sel,
	output reg key_derivation_en,
	output end_comp,
	output key_init,
	output key_gen,
	output mode_ctr,
	output mode_cbc,
	output last_round,
  output encrypt_decrypt,	
	input [1:0] operation_mode,
	input [1:0] aes_mode,
	input start,
	input disable_core,
	input clk,
	input rst_n
);

localparam ENCRYPTION     = 2'b00;
localparam KEY_DERIVATION = 2'b01;
localparam DECRYPTION     = 2'b10;
localparam DECRYP_W_DERIV = 2'b11;

localparam CBC = 2'b01;
localparam CTR = 2'b10;

localparam COL_0 = 3'b000;
localparam COL_1 = 3'b001;
localparam COL_2 = 3'b010;
localparam COL_3 = 3'b011;
localparam G_FUNCTION = 3'b100;

localparam COL        = 2'b00;
localparam MIXCOL_IN  = 2'b01;
localparam MIXCOL_OUT = 2'b10;

localparam KEY_0 = 2'b00;
localparam KEY_1 = 2'b01;
localparam KEY_2 = 2'b10;
localparam KEY_3 = 2'b11;

localparam SHIFT_ROWS = 2'b00;
localparam ADD_RK_OUT = 2'b01;
localparam INPUT      = 2'b10;

localparam KEY_HOST = 1'b0;
localparam KEY_OUT  = 1'b1;

localparam KEY_DIS  = 4'b0000;
localparam EN_KEY_0 = 4'b0001;
localparam EN_KEY_1 = 4'b0010;
localparam EN_KEY_2 = 4'b0100;
localparam EN_KEY_3 = 4'b1000;

localparam COL_DIS  = 4'b0000;
localparam EN_COL_0 = 4'b0001;
localparam EN_COL_1 = 4'b0010;
localparam EN_COL_2 = 4'b0100;
localparam EN_COL_3 = 4'b1000;
localparam COL_ALL  = 4'b1111;

localparam IV_CNT = 1'b1;
localparam IV_BUS = 1'b0;

localparam ENABLE = 1'b1;
localparam DISABLE = 1'b0;

localparam NUMBER_ROUND      = 4'd10;
localparam NUMBER_ROUND_INC  = 4'd11;
localparam INITIAL_ROUND     = 4'd00;

localparam IDLE        = 4'd00;
localparam ROUND0_COL0 = 4'd01;
localparam ROUND0_COL1 = 4'd02;
localparam ROUND0_COL2 = 4'd03;
localparam ROUND0_COL3 = 4'd04;
localparam ROUND_KEY0  = 4'd05;
localparam ROUND_COL0  = 4'd06;
localparam ROUND_COL1  = 4'd07;
localparam ROUND_COL2  = 4'd08;
localparam ROUND_COL3  = 4'd09;
localparam READY       = 4'd10;
localparam GEN_KEY0    = 4'd11;
localparam GEN_KEY1    = 4'd12;
localparam GEN_KEY2    = 4'd13;
localparam GEN_KEY3    = 4'd14;
localparam NOP         = 4'd15;

reg [3:0] state, next_state;
reg [3:0] rd_count;

reg rd_count_en;
wire op_key_derivation;
wire first_round;
wire [1:0] op_mode;
wire enc_dec;

wire last_round_and_mode_cbc_and_not_enc_dec;
wire last_round_and_mode_ctr;
wire last_round_special_case;
wire last_round_and_enc_dec;
wire not_last_round_and_enc_dec;
wire not_enc_dec;
wire not_last_round;

wire st_r0c0 = (state == ROUND0_COL0);
wire st_r0c1 = (state == ROUND0_COL1);
wire st_r0c2 = (state == ROUND0_COL2);
wire st_r0c3 = (state == ROUND0_COL3);
wire st_rc1  = (state == ROUND_COL1);
wire st_rc2  = (state == ROUND_COL2);
wire st_rc3  = (state == ROUND_COL3);
wire st_gfn  = (state == ROUND_KEY0) || (state == GEN_KEY0);

wire st_col1 = st_r0c1 || st_rc1;
wire st_col2 = st_r0c2 || st_rc2;
wire st_col3 = st_r0c3 || st_rc3;

always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			state <= IDLE;
		else
			if(disable_core)
				state <= IDLE;
			else
				state <= next_state;
	end

assign encrypt_decrypt = (op_mode == ENCRYPTION || op_mode == KEY_DERIVATION || state == GEN_KEY0   
			  ||   state == GEN_KEY1       ||state == GEN_KEY2   ||   state == GEN_KEY3       );

assign enc_dec = encrypt_decrypt | mode_ctr;
assign key_gen = (state == ROUND_KEY0);

assign op_key_derivation = (op_mode == KEY_DERIVATION);

assign mode_ctr = (aes_mode == CTR);
assign mode_cbc = (aes_mode == CBC);

assign key_init = start;

assign not_enc_dec = ~enc_dec;
assign not_last_round = ~last_round;
assign last_round_and_enc_dec = last_round & enc_dec;
assign not_last_round_and_enc_dec = not_last_round & enc_dec;
assign last_round_and_mode_cbc_and_not_enc_dec = last_round & mode_cbc & not_enc_dec;
assign last_round_and_mode_ctr = last_round & mode_ctr;
assign last_round_special_case = last_round_and_mode_cbc_and_not_enc_dec | last_round_and_mode_ctr;

assign op_mode = (mode_ctr) ? ENCRYPTION : operation_mode;

assign bypass_rk = st_r0c0 || st_r0c1 || st_r0c2 || st_r0c3;
assign sbox_sel = {st_gfn, (st_col2 || st_col3), (st_col1 || st_col3)};

always @(*)
	begin
		next_state = state;
		case(state)
			IDLE:
				begin
					if(!start)
						next_state = IDLE;
					else
						case(op_mode)
							ENCRYPTION    : next_state = ROUND0_COL0;
							DECRYPTION    : next_state = ROUND0_COL3;
							KEY_DERIVATION: next_state = GEN_KEY0;
							DECRYP_W_DERIV: next_state = GEN_KEY0;
							default       : next_state = IDLE;
						endcase
				end
			ROUND0_COL0: next_state = (enc_dec) ? ROUND0_COL1 : ROUND_KEY0; 
			ROUND0_COL1: next_state = (enc_dec) ? ROUND0_COL2 : ROUND0_COL0;
			ROUND0_COL2: next_state = (enc_dec) ? ROUND0_COL3 : ROUND0_COL1;
			ROUND0_COL3: next_state = (enc_dec) ? ROUND_KEY0 : ROUND0_COL2;
			ROUND_KEY0 :
				begin
					if(!first_round)
						next_state = (last_round) ? READY : NOP;
					else
						next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
				end
			NOP        : next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
			ROUND_COL0: next_state = (enc_dec) ? ROUND_COL1 : ROUND_KEY0;
			ROUND_COL1: next_state = (enc_dec) ? ROUND_COL2 : ROUND_COL0;
			ROUND_COL2: next_state = (enc_dec) ? ROUND_COL3 : ROUND_COL1;
			ROUND_COL3:
				begin
					if(last_round_and_enc_dec)
						next_state = READY;
					else
					next_state = (enc_dec) ? ROUND_KEY0 : ROUND_COL2;
				end
			GEN_KEY0   : next_state = GEN_KEY1;
			GEN_KEY1   : next_state = GEN_KEY2;
			GEN_KEY2   : next_state = GEN_KEY3;
			GEN_KEY3   :
				begin
					if(last_round)
						next_state = (op_key_derivation) ? READY : ROUND0_COL3;
					else
						next_state = GEN_KEY0;
				end
			READY      : next_state = IDLE;
		endcase
	end

assign end_comp = (state == READY)?ENABLE:DISABLE;

always @(*)
	begin
		rk_sel = COL;
		key_out_sel = KEY_0;
		col_sel = INPUT;
		key_sel = KEY_HOST;
		key_en = KEY_DIS;
		col_en = COL_DIS;
		rd_count_en = DISABLE;
		iv_cnt_en = DISABLE;
		iv_cnt_sel = IV_BUS;
		bypass_key_en = DISABLE;
		key_derivation_en = DISABLE;
		case(state)
			ROUND0_COL0:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_0;
					col_sel = (enc_dec) ? ADD_RK_OUT : SHIFT_ROWS;
					col_en =  (enc_dec) ? EN_COL_0 : COL_ALL;
				end
			ROUND0_COL1:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_1;
					col_sel = ADD_RK_OUT;
					col_en = EN_COL_1;
					if(!enc_dec)
						begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_1;
						end
				end
			ROUND0_COL2:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_2;
					col_sel = ADD_RK_OUT;
					col_en = EN_COL_2;
					if(!enc_dec)
						begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_2;
						end
				end
			ROUND0_COL3:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_3;
					col_sel = (enc_dec) ? SHIFT_ROWS : ADD_RK_OUT;
					col_en =  (enc_dec) ? COL_ALL : EN_COL_3;
					if(!enc_dec)
					begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_3;
					end
				end
			ROUND_KEY0:
				begin
					key_sel = KEY_OUT;
					key_en = EN_KEY_0;
					rd_count_en = ENABLE;
				end
			ROUND_COL0:
				begin
					rk_sel = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_0;
					key_sel = KEY_OUT;

					if(enc_dec)
						key_en = EN_KEY_1;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						begin
							if(not_enc_dec)
								col_sel = (last_round) ? ADD_RK_OUT : SHIFT_ROWS;
							else
								col_sel = ADD_RK_OUT;
						end
					if(enc_dec)
						col_en = EN_COL_0;
					else
						col_en = (last_round) ? EN_COL_0 : COL_ALL;
				end
			ROUND_COL1:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_1;
					key_sel = KEY_OUT;
					if(enc_dec)
						key_en = EN_KEY_2;
					else
						key_en = EN_KEY_1;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						col_sel = ADD_RK_OUT;
					col_en = EN_COL_1;
				end
			ROUND_COL2:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_2;
					key_sel = KEY_OUT;
					if(enc_dec)
						key_en = EN_KEY_3;
					else
						key_en = EN_KEY_2;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						col_sel = ADD_RK_OUT;
					col_en = EN_COL_2;
				end
			ROUND_COL3:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_3;
					key_sel = KEY_OUT;
					if(not_enc_dec)
						key_en = EN_KEY_3;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						begin
							if(enc_dec)
								col_sel = (last_round) ? ADD_RK_OUT : SHIFT_ROWS;
							else
								col_sel = ADD_RK_OUT;
						end
					if(enc_dec)
						col_en = (last_round) ? EN_COL_3 : COL_ALL;
					else
						col_en = EN_COL_3;
					if(last_round_and_mode_ctr)
						begin
							iv_cnt_en = ENABLE;
							iv_cnt_sel = IV_CNT;
						end
				end
			GEN_KEY0:
				begin
					rd_count_en = ENABLE;
				end
			GEN_KEY1:
				begin
					key_en = EN_KEY_1 | EN_KEY_0;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			GEN_KEY2:
				begin
					key_en = EN_KEY_2;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			GEN_KEY3:
				begin
					key_en = EN_KEY_3;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			READY:
				begin
					if(op_mode == KEY_DERIVATION)
						key_derivation_en = ENABLE;
				end
		endcase
	end

always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			rd_count <= INITIAL_ROUND;
		else
			if(state == IDLE || (state == GEN_KEY3 && last_round))
				rd_count <= INITIAL_ROUND;
			else 
				if(rd_count_en)
					rd_count <= rd_count + 1'b1;
	end

assign round = rd_count;
assign first_round = (rd_count == INITIAL_ROUND);
assign last_round  = (rd_count == NUMBER_ROUND || rd_count == NUMBER_ROUND_INC);

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_controller;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst_n;
  logic [1:0] operation_mode;
  logic [1:0] aes_mode;
  logic start;
  logic disable_core;
  logic [2:0] sbox_sel;
  logic [1:0] rk_sel;
  logic [1:0] key_out_sel;
  logic [1:0] col_sel;
  logic [3:0] key_en;
  logic [3:0] col_en;
  logic [3:0] round;
  logic bypass_rk;
  logic bypass_key_en;
  logic key_sel;
  logic iv_cnt_en;
  logic iv_cnt_sel;
  logic key_derivation_en;
  logic end_comp;
  logic key_init;
  logic key_gen;
  logic mode_ctr;
  logic mode_cbc;
  logic last_round;
  logic encrypt_decrypt;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  control_unit control_unit0 (
    .clk(clk),
    .rst_n(rst_n),
    .operation_mode(operation_mode),
    .aes_mode(aes_mode),
    .start(start),
    .disable_core(disable_core),
    .sbox_sel(sbox_sel),
    .rk_sel(rk_sel),
    .key_out_sel(key_out_sel),
    .col_sel(col_sel),
    .key_en(key_en),
    .col_en(col_en),
    .round(round),
    .bypass_rk(bypass_rk),
    .bypass_key_en(bypass_key_en),
    .key_sel(key_sel),
    .iv_cnt_en(iv_cnt_en),
    .iv_cnt_sel(iv_cnt_sel),
    .key_derivation_en(key_derivation_en),
    .end_comp(end_comp),
    .key_init(key_init),
    .key_gen(key_gen),
    .mode_ctr(mode_ctr),
    .mode_cbc(mode_cbc),
    .last_round(last_round),
    .encrypt_decrypt(encrypt_decrypt)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    operation_mode = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    aes_mode = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    start = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    disable_core = _rnd[0];
    rst_n = (($urandom % 32) == 0) ? 1'b0 : 1'b1;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    operation_mode = '0;
    aes_mode = '0;
    start = '0;
    disable_core = '0;
    // assert reset
    rst_n = 1'b0;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst_n = 1'b1;
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_controller);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.rtl_a:
// ---- file: controller.v0.v ----
module control_unit
(
	output     [ 2:0] sbox_sel,
	output reg [ 1:0] rk_sel,
	output reg [ 1:0] key_out_sel,
	output reg [ 1:0] col_sel,
	output reg [ 3:0] key_en,
	output reg [ 3:0] col_en,
	output     [ 3:0] round,
	output bypass_rk,
	output reg bypass_key_en,
	output reg key_sel,
	output reg iv_cnt_en,
	output reg iv_cnt_sel,
	output reg key_derivation_en,
	output end_comp,
	output key_init,
	output key_gen,
	output mode_ctr,
	output mode_cbc,
	output last_round,
  output encrypt_decrypt,	
	input [1:0] operation_mode,
	input [1:0] aes_mode,
	input start,
	input disable_core,
	input clk,
	input rst_n
);

localparam ENCRYPTION     = 2'b00;
localparam KEY_DERIVATION = 2'b01;
localparam DECRYPTION     = 2'b10;
localparam DECRYP_W_DERIV = 2'b11;

localparam CBC = 2'b01;
localparam CTR = 2'b10;

localparam COL_0 = 3'b000;
localparam COL_1 = 3'b001;
localparam COL_2 = 3'b010;
localparam COL_3 = 3'b011;
localparam G_FUNCTION = 3'b100;

localparam COL        = 2'b00;
localparam MIXCOL_IN  = 2'b01;
localparam MIXCOL_OUT = 2'b10;

localparam KEY_0 = 2'b00;
localparam KEY_1 = 2'b01;
localparam KEY_2 = 2'b10;
localparam KEY_3 = 2'b11;

localparam SHIFT_ROWS = 2'b00;
localparam ADD_RK_OUT = 2'b01;
localparam INPUT      = 2'b10;

localparam KEY_HOST = 1'b0;
localparam KEY_OUT  = 1'b1;

localparam KEY_DIS  = 4'b0000;
localparam EN_KEY_0 = 4'b0001;
localparam EN_KEY_1 = 4'b0010;
localparam EN_KEY_2 = 4'b0100;
localparam EN_KEY_3 = 4'b1000;

localparam COL_DIS  = 4'b0000;
localparam EN_COL_0 = 4'b0001;
localparam EN_COL_1 = 4'b0010;
localparam EN_COL_2 = 4'b0100;
localparam EN_COL_3 = 4'b1000;
localparam COL_ALL  = 4'b1111;

localparam IV_CNT = 1'b1;
localparam IV_BUS = 1'b0;

localparam ENABLE = 1'b1;
localparam DISABLE = 1'b0;

localparam NUMBER_ROUND      = 4'd10;
localparam NUMBER_ROUND_INC  = 4'd11;
localparam INITIAL_ROUND     = 4'd00;

localparam IDLE        = 4'd00;
localparam ROUND0_COL0 = 4'd01;
localparam ROUND0_COL1 = 4'd02;
localparam ROUND0_COL2 = 4'd03;
localparam ROUND0_COL3 = 4'd04;
localparam ROUND_KEY0  = 4'd05;
localparam ROUND_COL0  = 4'd06;
localparam ROUND_COL1  = 4'd07;
localparam ROUND_COL2  = 4'd08;
localparam ROUND_COL3  = 4'd09;
localparam READY       = 4'd10;
localparam GEN_KEY0    = 4'd11;
localparam GEN_KEY1    = 4'd12;
localparam GEN_KEY2    = 4'd13;
localparam GEN_KEY3    = 4'd14;
localparam NOP         = 4'd15;

reg [3:0] state, next_state;
reg [3:0] rd_count;

reg rd_count_en;
wire op_key_derivation;
wire first_round;
wire [1:0] op_mode;
wire enc_dec;

wire last_round_and_mode_cbc_and_not_enc_dec;
wire last_round_and_mode_ctr;
wire last_round_special_case;
wire last_round_and_enc_dec;
wire not_last_round_and_enc_dec;
wire not_enc_dec;
wire not_last_round;

wire st_r0c0 = (state == ROUND0_COL0);
wire st_r0c1 = (state == ROUND0_COL1);
wire st_r0c2 = (state == ROUND0_COL2);
wire st_r0c3 = (state == ROUND0_COL3);
wire st_rc1  = (state == ROUND_COL1);
wire st_rc2  = (state == ROUND_COL2);
wire st_rc3  = (state == ROUND_COL3);
wire st_gfn  = (state == ROUND_KEY0) || (state == GEN_KEY0);

wire st_col1 = st_r0c1 || st_rc1;
wire st_col2 = st_r0c2 || st_rc2;
wire st_col3 = st_r0c3 || st_rc3;

always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			state <= IDLE;
		else
			if(disable_core)
				state <= IDLE;
			else
				state <= next_state;
	end

assign encrypt_decrypt = (op_mode == ENCRYPTION || op_mode == KEY_DERIVATION || state == GEN_KEY0   
			  ||   state == GEN_KEY1       ||state == GEN_KEY2   ||   state == GEN_KEY3       );

assign enc_dec = encrypt_decrypt | mode_ctr;
assign key_gen = (state == ROUND_KEY0);

assign op_key_derivation = (op_mode == KEY_DERIVATION);

assign mode_ctr = (aes_mode == CTR);
assign mode_cbc = (aes_mode == CBC);

assign key_init = start;

assign not_enc_dec = ~enc_dec;
assign not_last_round = ~last_round;
assign last_round_and_enc_dec = last_round & enc_dec;
assign not_last_round_and_enc_dec = not_last_round & enc_dec;
assign last_round_and_mode_cbc_and_not_enc_dec = last_round & mode_cbc & not_enc_dec;
assign last_round_and_mode_ctr = last_round & mode_ctr;
assign last_round_special_case = last_round_and_mode_cbc_and_not_enc_dec | last_round_and_mode_ctr;

assign op_mode = (mode_ctr) ? ENCRYPTION : operation_mode;

assign bypass_rk = st_r0c0 || st_r0c1 || st_r0c2 || st_r0c3;
assign sbox_sel = {st_gfn, (st_col2 || st_col3), (st_col1 || st_col3)};

always @(*)
	begin
		next_state = state;
		case(state)
			IDLE:
				begin
					if(!start)
						next_state = IDLE;
					else
						case(op_mode)
							ENCRYPTION    : next_state = ROUND0_COL0;
							DECRYPTION    : next_state = ROUND0_COL3;
							KEY_DERIVATION: next_state = GEN_KEY0;
							DECRYP_W_DERIV: next_state = GEN_KEY0;
							default       : next_state = IDLE;
						endcase
				end
			ROUND0_COL0: next_state = (enc_dec) ? ROUND0_COL1 : ROUND_KEY0; 
			ROUND0_COL1: next_state = (enc_dec) ? ROUND0_COL2 : ROUND0_COL0;
			ROUND0_COL2: next_state = (enc_dec) ? ROUND0_COL3 : ROUND0_COL1;
			ROUND0_COL3: next_state = (enc_dec) ? ROUND_KEY0 : ROUND0_COL2;
			ROUND_KEY0 :
				begin
					if(!first_round)
						next_state = (last_round) ? READY : NOP;
					else
						next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
				end
			NOP        : next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
			ROUND_COL0: next_state = (enc_dec) ? ROUND_COL1 : ROUND_KEY0;
			ROUND_COL1: next_state = (enc_dec) ? ROUND_COL2 : ROUND_COL0;
			ROUND_COL2: next_state = (enc_dec) ? ROUND_COL3 : ROUND_COL1;
			ROUND_COL3:
				begin
					if(last_round_and_enc_dec)
						next_state = READY;
					else
					next_state = (enc_dec) ? ROUND_KEY0 : ROUND_COL2;
				end
			GEN_KEY0   : next_state = GEN_KEY1;
			GEN_KEY1   : next_state = GEN_KEY2;
			GEN_KEY2   : next_state = GEN_KEY3;
			GEN_KEY3   :
				begin
					if(last_round)
						next_state = (op_key_derivation) ? READY : ROUND0_COL3;
					else
						next_state = GEN_KEY0;
				end
			READY      : next_state = IDLE;
		endcase
	end

assign end_comp = (state == READY)?ENABLE:DISABLE;

always @(*)
	begin
		rk_sel = COL;
		key_out_sel = KEY_0;
		col_sel = INPUT;
		key_sel = KEY_HOST;
		key_en = KEY_DIS;
		col_en = COL_DIS;
		rd_count_en = DISABLE;
		iv_cnt_en = DISABLE;
		iv_cnt_sel = IV_BUS;
		bypass_key_en = DISABLE;
		key_derivation_en = DISABLE;
		case(state)
			ROUND0_COL0:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_0;
					col_sel = (enc_dec) ? ADD_RK_OUT : SHIFT_ROWS;
					col_en =  (enc_dec) ? EN_COL_0 : COL_ALL;
				end
			ROUND0_COL1:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_1;
					col_sel = ADD_RK_OUT;
					col_en = EN_COL_1;
					if(!enc_dec)
						begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_1;
						end
				end
			ROUND0_COL2:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_2;
					col_sel = ADD_RK_OUT;
					col_en = EN_COL_2;
					if(!enc_dec)
						begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_2;
						end
				end
			ROUND0_COL3:
				begin
					rk_sel   = COL;
					bypass_key_en = ENABLE;
					key_out_sel = KEY_3;
					col_sel = (enc_dec) ? SHIFT_ROWS : ADD_RK_OUT;
					col_en =  (enc_dec) ? COL_ALL : EN_COL_3;
					if(!enc_dec)
					begin
							key_sel = KEY_OUT;
							key_en =  EN_KEY_3;
					end
				end
			ROUND_KEY0:
				begin
					key_sel = KEY_OUT;
					key_en = EN_KEY_0;
					rd_count_en = ENABLE;
				end
			ROUND_COL0:
				begin
					rk_sel = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_0;
					key_sel = KEY_OUT;

					if(enc_dec)
						key_en = EN_KEY_1;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						begin
							if(not_enc_dec)
								col_sel = (last_round) ? ADD_RK_OUT : SHIFT_ROWS;
							else
								col_sel = ADD_RK_OUT;
						end
					if(enc_dec)
						col_en = EN_COL_0;
					else
						col_en = (last_round) ? EN_COL_0 : COL_ALL;
				end
			ROUND_COL1:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_1;
					key_sel = KEY_OUT;
					if(enc_dec)
						key_en = EN_KEY_2;
					else
						key_en = EN_KEY_1;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						col_sel = ADD_RK_OUT;
					col_en = EN_COL_1;
				end
			ROUND_COL2:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_2;
					key_sel = KEY_OUT;
					if(enc_dec)
						key_en = EN_KEY_3;
					else
						key_en = EN_KEY_2;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						col_sel = ADD_RK_OUT;
					col_en = EN_COL_2;
				end
			ROUND_COL3:
				begin
					rk_sel   = (last_round) ? MIXCOL_IN : MIXCOL_OUT;
					key_out_sel = KEY_3;
					key_sel = KEY_OUT;
					if(not_enc_dec)
						key_en = EN_KEY_3;
					if(last_round_special_case)
						col_sel = INPUT;
					else
						begin
							if(enc_dec)
								col_sel = (last_round) ? ADD_RK_OUT : SHIFT_ROWS;
							else
								col_sel = ADD_RK_OUT;
						end
					if(enc_dec)
						col_en = (last_round) ? EN_COL_3 : COL_ALL;
					else
						col_en = EN_COL_3;
					if(last_round_and_mode_ctr)
						begin
							iv_cnt_en = ENABLE;
							iv_cnt_sel = IV_CNT;
						end
				end
			GEN_KEY0:
				begin
					rd_count_en = ENABLE;
				end
			GEN_KEY1:
				begin
					key_en = EN_KEY_1 | EN_KEY_0;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			GEN_KEY2:
				begin
					key_en = EN_KEY_2;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			GEN_KEY3:
				begin
					key_en = EN_KEY_3;
					key_sel = KEY_OUT;
					bypass_key_en = ENABLE;
				end
			READY:
				begin
					if(op_mode == KEY_DERIVATION)
						key_derivation_en = ENABLE;
				end
		endcase
	end

always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			rd_count <= INITIAL_ROUND;
		else
			if(state == IDLE || (state == GEN_KEY3 && last_round))
				rd_count <= INITIAL_ROUND;
			else 
				if(rd_count_en)
					rd_count <= rd_count + 1'b1;
	end

assign round = rd_count;
assign first_round = (rd_count == INITIAL_ROUND);
assign last_round  = (rd_count == NUMBER_ROUND || rd_count == NUMBER_ROUND_INC);

endmodule

state.rtl_b:
// ---- file: controller.v0.v ----
module control_unit
(
	output reg [ 2:0] sbox_sel,
	output reg [ 1:0] rk_sel,
	output reg [ 1:0] key_out_sel,
	output reg [ 1:0] col_sel,
	output reg [ 3:0] key_en,
	output reg [ 3:0] col_en,
	output     [ 3:0] round,
	output reg bypass_rk,
	output reg bypass_key_en,
	output reg key_sel,
	output reg iv_cnt_en,
	output reg iv_cnt_sel,
	output reg key_derivation_en,
	output end_comp,
	output key_init,
	output key_gen,
	output mode_ctr,
	output mode_cbc,
	output last_round,
	output encrypt_decrypt,	
	input [1:0] operation_mode,
	input [1:0] aes_mode,
	input start,
	input disable_core,
	input clk,
	input rst_n
);

//=============================================================================
// Operation Modes
//=============================================================================
localparam ENCRYPTION     = 2'b00;
localparam KEY_DERIVATION = 2'b01;
localparam DECRYPTION     = 2'b10;
localparam DECRYP_W_DERIV = 2'b11;

//=============================================================================
// AES Modes
//=============================================================================
localparam CBC = 2'b01;
localparam CTR = 2'b10;

//=============================================================================
// Datapath Select Values
//=============================================================================
localparam COL_0      = 3'b000;
localparam G_FUNCTION = 3'b100;

localparam COL        = 2'b00;
localparam MIXCOL_IN  = 2'b01;
localparam MIXCOL_OUT = 2'b10;

localparam KEY_0 = 2'b00;

localparam SHIFT_ROWS = 2'b00;
localparam ADD_RK_OUT = 2'b01;
localparam INPUT      = 2'b10;

localparam KEY_HOST = 1'b0;
localparam KEY_OUT  = 1'b1;

localparam KEY_DIS  = 4'b0000;
localparam EN_KEY_0 = 4'b0001;
localparam EN_KEY_1 = 4'b0010;
localparam EN_KEY_2 = 4'b0100;
localparam EN_KEY_3 = 4'b1000;

localparam COL_DIS = 4'b0000;
localparam COL_ALL = 4'b1111;

localparam IV_CNT = 1'b1;
localparam IV_BUS = 1'b0;

localparam ENABLE  = 1'b1;
localparam DISABLE = 1'b0;

localparam INITIAL_ROUND = 4'd0;

//=============================================================================
// FSM STATES
// Encoding:
//   00xx : special states
//   01cc : ROUND0 column cc
//   10cc : ROUND column cc
//   11kk : GEN_KEY kk
//=============================================================================
localparam IDLE        = 4'b0000;
localparam ROUND_KEY0  = 4'b0001;
localparam READY       = 4'b0010;
localparam NOP         = 4'b0011;

localparam ROUND0_COL0 = 4'b0100;
localparam ROUND0_COL3 = 4'b0111;

localparam ROUND_COL0  = 4'b1000;
localparam ROUND_COL3  = 4'b1011;

localparam GEN_KEY0    = 4'b1100;
localparam GEN_KEY3    = 4'b1111;

reg [3:0] state, next_state;
reg [3:0] rd_count;

wire enc_dec;
wire op_key_derivation;
wire first_round;
wire not_enc_dec;
wire not_last_round;
wire last_round_and_enc_dec;
wire last_round_and_mode_ctr;
wire last_round_special_case;

wire grp_r0;
wire grp_rc;
wire grp_gen;
wire grp_col;

wire col0;
wire col1;
wire col2;
wire col3;
wire [3:0] col_onehot;
wire [3:0] col_next_onehot;

wire st_idle;
wire st_rkey;
wire st_ready;
wire st_gen0;
wire st_gen3;
wire rd_count_en;

assign mode_ctr = aes_mode[1] & ~aes_mode[0];
assign mode_cbc = ~aes_mode[1] & aes_mode[0];

assign grp_r0  = ~state[3] &  state[2];
assign grp_rc  =  state[3] & ~state[2];
assign grp_gen =  state[3] &  state[2];
assign grp_col =  state[3] ^  state[2];

assign col0 = ~state[1] & ~state[0];
assign col1 = ~state[1] &  state[0];
assign col2 =  state[1] & ~state[0];
assign col3 =  state[1] &  state[0];

assign col_onehot      = {col3, col2, col1, col0};
assign col_next_onehot = {col2, col1, col0, 1'b0};

assign st_idle  = ~state[3] & ~state[2] & col0;
assign st_rkey  = ~state[3] & ~state[2] & col1;
assign st_ready = ~state[3] & ~state[2] & col2;
assign st_gen0  =  grp_gen & col0;
assign st_gen3  =  grp_gen & col3;

assign encrypt_decrypt = mode_ctr | ~operation_mode[1] | grp_gen;
assign enc_dec = encrypt_decrypt;

assign op_key_derivation = ~mode_ctr & ~operation_mode[1] & operation_mode[0];

assign key_gen = st_rkey;
assign key_init = start;

assign not_enc_dec = ~enc_dec;
assign not_last_round = ~last_round;
assign last_round_and_enc_dec = last_round & enc_dec;
assign last_round_and_mode_ctr = last_round & mode_ctr;
assign last_round_special_case = (last_round & mode_cbc & not_enc_dec) | last_round_and_mode_ctr;

assign rd_count_en = st_rkey | st_gen0;

// State Flops Definition
always @(posedge clk, negedge rst_n)
begin
	if(!rst_n)
		state <= IDLE;
	else if(disable_core)
		state <= IDLE;
	else
		state <= next_state;
end

// Next State Logic
always @(*)
begin
	next_state = state;

	case (state[3:2])
		2'b00: begin
			case (state[1:0])
				2'b00: begin // IDLE
					if(!start)
						next_state = IDLE;
					else if(mode_ctr)
						next_state = ROUND0_COL0;
					else begin
						case(operation_mode)
							ENCRYPTION     : next_state = ROUND0_COL0;
							DECRYPTION     : next_state = ROUND0_COL3;
							KEY_DERIVATION : next_state = GEN_KEY0;
							DECRYP_W_DERIV : next_state = GEN_KEY0;
							default        : next_state = IDLE;
						endcase
					end
				end

				2'b01: begin // ROUND_KEY0
					if(!first_round)
						next_state = last_round ? READY : NOP;
					else
						next_state = enc_dec ? ROUND_COL0 : ROUND_COL3;
				end

				2'b10: begin // READY
					next_state = IDLE;
				end

				2'b11: begin // NOP
					next_state = enc_dec ? ROUND_COL0 : ROUND_COL3;
				end
			endcase
		end

		2'b01: begin // ROUND0_COL*
			if(enc_dec)
				next_state = col3 ? ROUND_KEY0 : (state + 4'd1);
			else
				next_state = col0 ? ROUND_KEY0 : (state - 4'd1);
		end

		2'b10: begin // ROUND_COL*
			if(enc_dec) begin
				if(col3)
					next_state = last_round ? READY : ROUND_KEY0;
				else
					next_state = state + 4'd1;
			end else begin
				next_state = col0 ? ROUND_KEY0 : (state - 4'd1);
			end
		end

		2'b11: begin // GEN_KEY*
			if(col3) begin
				if(last_round)
					next_state = op_key_derivation ? READY : ROUND0_COL3;
				else
					next_state = GEN_KEY0;
			end else begin
				next_state = state + 4'd1;
			end
		end
	endcase
end

// Output Logic
assign end_comp = st_ready ? ENABLE : DISABLE;

always @(*)
begin
	sbox_sel = COL_0;
	rk_sel = COL;
	bypass_rk = DISABLE;
	key_out_sel = KEY_0;
	col_sel = INPUT;
	key_sel = KEY_HOST;
	key_en = KEY_DIS;
	col_en = COL_DIS;
	iv_cnt_en = DISABLE;
	iv_cnt_sel = IV_BUS;
	bypass_key_en = DISABLE;
	key_derivation_en = DISABLE;

	if(st_rkey || st_gen0)
		sbox_sel = G_FUNCTION;
	else if(grp_col)
		sbox_sel = {1'b0, state[1:0]};

	if(grp_col)
		key_out_sel = state[1:0];

	if(grp_rc)
		rk_sel = last_round ? MIXCOL_IN : MIXCOL_OUT;

	bypass_rk = grp_r0 ? ENABLE : DISABLE;
	bypass_key_en = (grp_r0 || (grp_gen && !col0)) ? ENABLE : DISABLE;

	if(st_rkey || grp_rc || (grp_gen && !col0) || (grp_r0 && !col0 && not_enc_dec))
		key_sel = KEY_OUT;

	if(st_rkey) begin
		key_en = EN_KEY_0;
	end else if(grp_r0 && not_enc_dec) begin
		key_en = col0 ? KEY_DIS : col_onehot;
	end else if(grp_rc) begin
		key_en = enc_dec ? col_next_onehot : (col0 ? KEY_DIS : col_onehot);
	end else if(grp_gen) begin
		if(col1)
			key_en = EN_KEY_1 | EN_KEY_0;
		else if(col2)
			key_en = EN_KEY_2;
		else if(col3)
			key_en = EN_KEY_3;
	end

	if(grp_r0) begin
		if((enc_dec && col3) || (not_enc_dec && col0))
			col_sel = SHIFT_ROWS;
		else
			col_sel = ADD_RK_OUT;
	end else if(grp_rc) begin
		if(last_round_special_case)
			col_sel = INPUT;
		else if((enc_dec && col3 && not_last_round) ||
		        (not_enc_dec && col0 && not_last_round))
			col_sel = SHIFT_ROWS;
		else
			col_sel = ADD_RK_OUT;
	end

	if(grp_r0) begin
		if(enc_dec)
			col_en = col3 ? COL_ALL : col_onehot;
		else
			col_en = col0 ? COL_ALL : col_onehot;
	end else if(grp_rc) begin
		if(enc_dec) begin
			if(col3)
				col_en = last_round ? col_onehot : COL_ALL;
			else
				col_en = col_onehot;
		end else begin
			if(col0)
				col_en = last_round ? col_onehot : COL_ALL;
			else
				col_en = col_onehot;
		end
	end

	if(grp_rc && col3 && last_round_and_mode_ctr) begin
		iv_cnt_en = ENABLE;
		iv_cnt_sel = IV_CNT;
	end

	if(st_ready && op_key_derivation)
		key_derivation_en = ENABLE;
end

// Round Counter
always @(posedge clk, negedge rst_n)
begin
	if(!rst_n)
		rd_count <= INITIAL_ROUND;
	else if(st_idle || (st_gen3 && last_round))
		rd_count <= INITIAL_ROUND;
	else if(rd_count_en)
		rd_count <= rd_count + 1'b1;
end

assign round = rd_count;
assign first_round = ~(|rd_count);
assign last_round  = rd_count[3] & ~rd_count[2] & rd_count[1];

endmodule

state.tb_power:
`timescale 1ns/1ps
`ifndef CLK_PERIOD_NS
  `define CLK_PERIOD_NS 2.0
`endif
module tb_pt_controller;
  localparam real CLK_HALF = `CLK_PERIOD_NS / 2.0;
  localparam real SETTLE_NS = 2.0;
  localparam int  N_PT = 4000;
  localparam int  RESET_CYCLES = 8;
  logic clk;
  logic rst_n;
  logic [1:0] operation_mode;
  logic [1:0] aes_mode;
  logic start;
  logic disable_core;
  logic [2:0] sbox_sel;
  logic [1:0] rk_sel;
  logic [1:0] key_out_sel;
  logic [1:0] col_sel;
  logic [3:0] key_en;
  logic [3:0] col_en;
  logic [3:0] round;
  logic bypass_rk;
  logic bypass_key_en;
  logic key_sel;
  logic iv_cnt_en;
  logic iv_cnt_sel;
  logic key_derivation_en;
  logic end_comp;
  logic key_init;
  logic key_gen;
  logic mode_ctr;
  logic mode_cbc;
  logic last_round;
  logic encrypt_decrypt;
  logic [2047:0] _rnd;
  always #(CLK_HALF) clk = ~clk;
  control_unit control_unit0 (
    .clk(clk),
    .rst_n(rst_n),
    .operation_mode(operation_mode),
    .aes_mode(aes_mode),
    .start(start),
    .disable_core(disable_core),
    .sbox_sel(sbox_sel),
    .rk_sel(rk_sel),
    .key_out_sel(key_out_sel),
    .col_sel(col_sel),
    .key_en(key_en),
    .col_en(col_en),
    .round(round),
    .bypass_rk(bypass_rk),
    .bypass_key_en(bypass_key_en),
    .key_sel(key_sel),
    .iv_cnt_en(iv_cnt_en),
    .iv_cnt_sel(iv_cnt_sel),
    .key_derivation_en(key_derivation_en),
    .end_comp(end_comp),
    .key_init(key_init),
    .key_gen(key_gen),
    .mode_ctr(mode_ctr),
    .mode_cbc(mode_cbc),
    .last_round(last_round),
    .encrypt_decrypt(encrypt_decrypt)
  );
  task automatic drive_inputs();
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    operation_mode = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    aes_mode = _rnd[1:0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    start = _rnd[0];
    _rnd = '0;
    for (int _i = 0; _i < 1; _i++) _rnd = (_rnd << 32) | $urandom();
    disable_core = _rnd[0];
    rst_n = (($urandom % 32) == 0) ? 1'b0 : 1'b1;
  endtask
  initial begin
    void'($urandom(32'hC0DE0042));
    clk = 1'b0;
    operation_mode = '0;
    aes_mode = '0;
    start = '0;
    disable_core = '0;
    // assert reset
    rst_n = 1'b0;
    repeat (RESET_CYCLES) @(negedge clk);
    // release reset
    rst_n = 1'b1;
    $dumpfile("power.vcd");
    $dumpvars(0, tb_pt_controller);
    $dumpon;
    for (int _k = 0; _k < N_PT; _k++) begin @(negedge clk); drive_inputs(); end
    $dumpoff;
    $finish;
  end
  initial begin #(CLK_HALF * 2 * (N_PT + RESET_CYCLES + 200)); $display("tb_pt TIMEOUT"); $finish; end
endmodule

state.rtl_a:
// ---- file: tv80.v0.v ----
module tv80_alu (/*AUTOARG*/
  // Outputs
  Q, F_Out, 
  // Inputs
  Arith16, Z16, ALU_Op, IR, ISet, BusA, BusB, F_In
  );

  parameter		Mode   = 0;
  parameter		Flag_C = 0;
  parameter		Flag_N = 1;
  parameter		Flag_P = 2;
  parameter		Flag_X = 3;
  parameter		Flag_H = 4;
  parameter		Flag_Y = 5;
  parameter		Flag_Z = 6;
  parameter		Flag_S = 7;

  input 		Arith16;
  input 		Z16;
  input [3:0]           ALU_Op ;
  input [5:0]           IR;
  input [1:0]           ISet;
  input [7:0]           BusA;
  input [7:0]           BusB;
  input [7:0]           F_In;
  output [7:0]          Q;
  output [7:0]          F_Out;
  reg [7:0]             Q;
  reg [7:0]             F_Out;

  function [4:0] AddSub4;
    input [3:0] A;
    input [3:0] B;
    input Sub;
    input Carry_In;
    begin
      AddSub4 = { 1'b0, A } + { 1'b0, (Sub)?~B:B } + Carry_In;
    end
  endfunction

  function [3:0] AddSub3;
    input [2:0] A;
    input [2:0] B;
    input Sub;
    input Carry_In;
    begin
      AddSub3 = { 1'b0, A } + { 1'b0, (Sub)?~B:B } + Carry_In;
    end
  endfunction

  function [1:0] AddSub1;
    input A;
    input B;
    input Sub;
    input Carry_In;
    begin
      AddSub1 = { 1'b0, A } + { 1'b0, (Sub)?~B:B } + Carry_In;
    end
  endfunction

  reg UseCarry;
  reg Carry7_v;
  reg OverFlow_v;
  reg HalfCarry_v;
  reg Carry_v;
  reg [7:0] Q_v;

  always @*
    begin
      UseCarry = ~ ALU_Op[2] && ALU_Op[0];
      { HalfCarry_v, Q_v[3:0] } = AddSub4(BusA[3:0], BusB[3:0], ALU_Op[1], ALU_Op[1] ^ (UseCarry && F_In[Flag_C]) );
      { Carry7_v, Q_v[6:4]  } = AddSub3(BusA[6:4], BusB[6:4], ALU_Op[1], HalfCarry_v);
      { Carry_v, Q_v[7] } = AddSub1(BusA[7], BusB[7], ALU_Op[1], Carry7_v);
      OverFlow_v = Carry_v ^ Carry7_v;
    end

  reg [7:0] Q_t;
  reg [8:0] DAA_Q;
  reg       BitVal;

  always @*
    begin
      Q_t = 8'hxx;
      DAA_Q = {9{1'bx}};
      BitVal = 1'bx;

      F_Out = F_In;
      case (ALU_Op)
	4'b0000, 4'b0001,  4'b0010, 4'b0011, 4'b0100, 4'b0101, 4'b0110, 4'b0111 :
          begin
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_C] = 1'b0;

	    case (ALU_Op[2:0])

	      3'b000, 3'b001 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_C] = Carry_v;
		  F_Out[Flag_H] = HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end

	      3'b010, 3'b011, 3'b111 :
                begin
		  Q_t = Q_v;
		  F_Out[Flag_N] = 1'b1;
		  F_Out[Flag_C] = ~ Carry_v;
		  F_Out[Flag_H] = ~ HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end

	      3'b100 :
                begin
		  Q_t[7:0] = BusA & BusB;
		  F_Out[Flag_H] = 1'b1;
                end

	      3'b101 :
                begin
		  Q_t[7:0] = BusA ^ BusB;
		  F_Out[Flag_H] = 1'b0;
                end

	      default :
                begin
		  Q_t[7:0] = BusA | BusB;
		  F_Out[Flag_H] = 1'b0;
                end

	    endcase

	    if (ALU_Op[2:0] == 3'b111 ) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end 
            else 
              begin
		F_Out[Flag_X] = Q_t[3];
		F_Out[Flag_Y] = Q_t[5];
	      end

	    if (Q_t[7:0] == 8'b00000000 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
		if (Z16 == 1'b1 ) 
		    F_Out[Flag_Z] = F_In[Flag_Z];
	      end 
            else 
		F_Out[Flag_Z] = 1'b0;

	    F_Out[Flag_S] = Q_t[7];
	    case (ALU_Op[2:0])
	      3'b000, 3'b001, 3'b010, 3'b011, 3'b111 : ;
	      default :
	        F_Out[Flag_P] = ~(^Q_t);                    
	    endcase

	    if (Arith16 == 1'b1 ) 
              begin
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
		F_Out[Flag_P] = F_In[Flag_P];
	      end
          end

	4'b1100 :
          begin
	    F_Out[Flag_H] = F_In[Flag_H];
	    F_Out[Flag_C] = F_In[Flag_C];
	    DAA_Q[7:0] = BusA;
	    DAA_Q[8] = 1'b0;
	    if (F_In[Flag_N] == 1'b0 ) 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1 ) 
                  begin
		    if ((DAA_Q[3:0] > 9) ) 
			F_Out[Flag_H] = 1'b1;
                    else 
			F_Out[Flag_H] = 1'b0;
		    DAA_Q = DAA_Q + 6;
		  end

		if (DAA_Q[8:4] > 9 || F_In[Flag_C] == 1'b1 ) 
		    DAA_Q = DAA_Q + 96;
	      end 
            else 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1 ) 
                  begin
		    if (DAA_Q[3:0] > 5 ) 
			F_Out[Flag_H] = 1'b0;
		    DAA_Q[7:0] = DAA_Q[7:0] - 6;
		  end
		if (BusA > 153 || F_In[Flag_C] == 1'b1 ) 
		    DAA_Q = DAA_Q - 352;
	      end

	    F_Out[Flag_X] = DAA_Q[3];
	    F_Out[Flag_Y] = DAA_Q[5];
	    F_Out[Flag_C] = F_In[Flag_C] || DAA_Q[8];
	    Q_t = DAA_Q[7:0];

	    if (DAA_Q[7:0] == 8'b00000000 ) 
		F_Out[Flag_Z] = 1'b1;
            else 
		F_Out[Flag_Z] = 1'b0;

	    F_Out[Flag_S] = DAA_Q[7];
	    F_Out[Flag_P] = ~ (^DAA_Q);
          end

	4'b1101, 4'b1110 :
          begin
	    Q_t[7:4] = BusA[7:4];
	    if (ALU_Op[0] == 1'b1 ) 
		Q_t[3:0] = BusB[7:4];
            else 
		Q_t[3:0] = BusB[3:0];
	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    if (Q_t[7:0] == 8'b00000000 ) 
		F_Out[Flag_Z] = 1'b1;
            else 
		F_Out[Flag_Z] = 1'b0;
	    F_Out[Flag_S] = Q_t[7];
            F_Out[Flag_P] = ~(^Q_t);
          end

	4'b1001 :
          begin
	    BitVal = BusB[IR[5:3]];
	    Q_t[7:0] = 8'b00000000;
	    Q_t[IR[5:3]] = BitVal;
	    F_Out[Flag_S] = Q_t[7];
	    if (BitVal == 1'b0 ) 
              begin
		F_Out[Flag_Z] = 1'b1;
		F_Out[Flag_P] = 1'b1;
	      end 
            else 
              begin
		F_Out[Flag_Z] = 1'b0;
		F_Out[Flag_P] = 1'b0;
	      end
	    F_Out[Flag_H] = 1'b1;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = 1'b0;
	    F_Out[Flag_Y] = 1'b0;
	    if (IR[2:0] != 3'b110 ) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end
          end

	4'b1010 :
          begin
	    Q_t[7:0] = BusB;
	    Q_t[IR[5:3]] = 1'b1;
          end

	4'b1011 :
          begin
	    Q_t[7:0] = BusB;
	    Q_t[IR[5:3]] = 1'b0;
          end

	4'b1000 :
          begin
	    case (IR[5:3])
	      3'b000 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = BusA[7];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b010 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b001 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[0];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b011 :
                begin                        
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b100 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = 1'b0;
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b110 :
                begin
		  if (Mode == 3 ) 
                    begin
		      Q_t[7:4] = BusA[3:0];
		      Q_t[3:0] = BusA[7:4];
		      F_Out[Flag_C] = 1'b0;                            
		    end 
                  else 
                    begin
		      Q_t[7:1] = BusA[6:0];
		      Q_t[0] = 1'b1;
		      F_Out[Flag_C] = BusA[7];
		    end
                end

	      3'b101 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[7];
		  F_Out[Flag_C] = BusA[0];
                end

	      default :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = 1'b0;
		  F_Out[Flag_C] = BusA[0];
                end
	    endcase

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_S] = Q_t[7];
	    if (Q_t[7:0] == 8'b00000000 ) 
		F_Out[Flag_Z] = 1'b1;
            else 
		F_Out[Flag_Z] = 1'b0;
            F_Out[Flag_P] = ~(^Q_t);

	    if (ISet == 2'b00 ) 
              begin
		F_Out[Flag_P] = F_In[Flag_P];
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
	      end
          end

	default :
	  ;

      endcase

      Q = Q_t;
    end

endmodule

