                begin
		  Q_t = Q_v;
		  F_Out[Flag_N] = 1'b1;
		  F_Out[Flag_C] = ~Carry_v;
		  F_Out[Flag_H] = ~HalfCarry_v;
		  F_Out[Flag_P] = OverFlow_v;
                end

	      3'b100 :
                begin
		  Q_t = BusA & BusB;
		  F_Out[Flag_H] = 1'b1;
                end

	      3'b101 :
                begin
		  Q_t = BusA ^ BusB;
		  F_Out[Flag_H] = 1'b0;
                end

	      default :
                begin
		  Q_t = BusA | BusB;
		  F_Out[Flag_H] = 1'b0;
                end
	    endcase

	    if (ALU_Op[2:0] == 3'b111) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end 
            else 
              begin
		F_Out[Flag_X] = Q_t[3];
		F_Out[Flag_Y] = Q_t[5];
	      end

	    F_Out[Flag_Z] = (~|Q_t) & (~Z16 | F_In[Flag_Z]);
	    F_Out[Flag_S] = Q_t[7];

	    if (Arith16) 
              begin
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
		F_Out[Flag_P] = F_In[Flag_P];
	      end
          end

	4'b1100 :
          begin
	    F_Out[Flag_H] = F_In[Flag_H];
	    F_Out[Flag_C] = F_In[Flag_C];
	    DAA_Q[7:0] = BusA;
	    DAA_Q[8] = 1'b0;
	    if (F_In[Flag_N] == 1'b0) 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1) 
                  begin
		    F_Out[Flag_H] = (DAA_Q[3:0] > 9);
		    DAA_Q = DAA_Q + 6;
		  end

		if (DAA_Q[8:4] > 9 || F_In[Flag_C] == 1'b1) 
                  begin
		    DAA_Q = DAA_Q + 96;
		  end
	      end 
            else 
              begin
		if (DAA_Q[3:0] > 9 || F_In[Flag_H] == 1'b1) 
                  begin
		    if (DAA_Q[3:0] > 5) 
                      begin
			F_Out[Flag_H] = 1'b0;
		      end
		    DAA_Q[7:0] = DAA_Q[7:0] - 6;
		  end
		if (BusA > 153 || F_In[Flag_C] == 1'b1) 
                  begin
		    DAA_Q = DAA_Q - 352;
		  end
	      end

	    F_Out[Flag_X] = DAA_Q[3];
	    F_Out[Flag_Y] = DAA_Q[5];
	    F_Out[Flag_C] = F_In[Flag_C] || DAA_Q[8];
	    Q_t = DAA_Q[7:0];
	    F_Out[Flag_Z] = ~|DAA_Q[7:0];
	    F_Out[Flag_S] = DAA_Q[7];
	    F_Out[Flag_P] = ~(^DAA_Q);
          end

	4'b1101, 4'b1110 :
          begin
	    Q_t[7:4] = BusA[7:4];
	    if (ALU_Op[0]) 
              begin
		Q_t[3:0] = BusB[7:4];
	      end 
            else 
              begin
		Q_t[3:0] = BusB[3:0];
	      end
	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_Z] = ~|Q_t;
	    F_Out[Flag_S] = Q_t[7];
          end

	4'b1001 :
          begin
	    Q_t = BusB & BitMask;
	    F_Out[Flag_S] = Q_t[7];
	    F_Out[Flag_Z] = ~|Q_t;
	    F_Out[Flag_P] = ~|Q_t;
	    F_Out[Flag_H] = 1'b1;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = 1'b0;
	    F_Out[Flag_Y] = 1'b0;
	    if (IR[2:0] != 3'b110) 
              begin
		F_Out[Flag_X] = BusB[3];
		F_Out[Flag_Y] = BusB[5];
	      end
          end

	4'b1010 :
	  Q_t = BusB | BitMask;

	4'b1011 :
	  Q_t = BusB & ~BitMask;

	4'b1000 :
          begin
	    case (IR[5:3])
	      3'b000 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = BusA[7];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b010 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b001 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[0];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b011 :
                begin                        
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = F_In[Flag_C];
		  F_Out[Flag_C] = BusA[0];
                end

	      3'b100 :
                begin
		  Q_t[7:1] = BusA[6:0];
		  Q_t[0] = 1'b0;
		  F_Out[Flag_C] = BusA[7];
                end

	      3'b110 :
                begin
		  if (Mode == 3) 
                    begin
		      Q_t[7:4] = BusA[3:0];
		      Q_t[3:0] = BusA[7:4];
		      F_Out[Flag_C] = 1'b0;
		    end 
                  else 
                    begin
		      Q_t[7:1] = BusA[6:0];
		      Q_t[0] = 1'b1;
		      F_Out[Flag_C] = BusA[7];
		    end
                end

	      3'b101 :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = BusA[7];
		  F_Out[Flag_C] = BusA[0];
                end

	      default :
                begin
		  Q_t[6:0] = BusA[7:1];
		  Q_t[7] = 1'b0;
		  F_Out[Flag_C] = BusA[0];
                end
	    endcase

	    F_Out[Flag_H] = 1'b0;
	    F_Out[Flag_N] = 1'b0;
	    F_Out[Flag_X] = Q_t[3];
	    F_Out[Flag_Y] = Q_t[5];
	    F_Out[Flag_S] = Q_t[7];
	    F_Out[Flag_Z] = ~|Q_t;

	    if (ISet == 2'b00) 
              begin
		F_Out[Flag_P] = F_In[Flag_P];
		F_Out[Flag_S] = F_In[Flag_S];
		F_Out[Flag_Z] = F_In[Flag_Z];
	      end
          end

	default :
	  ;
      endcase

      if (((ALU_Op[3] == 1'b0) && ALU_Op[2] && ~(ALU_Op[1] & ALU_Op[0]) && ~Arith16) ||
          (ALU_Op == 4'b1101) || (ALU_Op == 4'b1110) ||
          ((ALU_Op == 4'b1000) && (ISet != 2'b00)))
        F_Out[Flag_P] = ~(^Q_t);

      Q = Q_t;
    end

endmodule

