// ---- file: controller.v0.v ----
module control_unit
(
	output reg [ 2:0] sbox_sel,
	output reg [ 1:0] rk_sel,
	output reg [ 1:0] key_out_sel,
	output reg [ 1:0] col_sel,
	output reg [ 3:0] key_en,
	output reg [ 3:0] col_en,
	output     [ 3:0] round,
	output reg bypass_rk,
	output reg bypass_key_en,
	output reg key_sel,
	output reg iv_cnt_en,
	output reg iv_cnt_sel,
	output reg key_derivation_en,
	output end_comp,
	output key_init,
	output key_gen,
	output mode_ctr,
	output mode_cbc,
	output last_round,
	output encrypt_decrypt,	
	input [1:0] operation_mode,
	input [1:0] aes_mode,
	input start,
	input disable_core,
	input clk,
	input rst_n
);

//=====================================================================================
// Memory Mapped Registers Address
//=====================================================================================
localparam AES_CR    = 4'd00;
localparam AES_SR    = 4'd01;
localparam AES_DINR  = 4'd02;
localparam AES_DOUTR = 4'd03;
localparam AES_KEYR0 = 4'd04;
localparam AES_KEYR1 = 4'd05;
localparam AES_KEYR2 = 4'd06;
localparam AES_KEYR3 = 4'd07;
localparam AES_IVR0  = 4'd08;
localparam AES_IVR1  = 4'd09;
localparam AES_IVR2  = 4'd10;
localparam AES_IVR3  = 4'd11;

//=============================================================================
// Operation Modes
//=============================================================================
localparam ENCRYPTION     = 2'b00;
localparam KEY_DERIVATION = 2'b01;
localparam DECRYPTION     = 2'b10;
localparam DECRYP_W_DERIV = 2'b11;

//=============================================================================
// AES Modes
//=============================================================================
localparam ECB = 2'b00;
localparam CBC = 2'b01;
localparam CTR = 2'b10;

//=============================================================================
// SBOX SEL
//=============================================================================
localparam COL_0 = 3'b000;
localparam COL_1 = 3'b001;
localparam COL_2 = 3'b010;
localparam COL_3 = 3'b011;
localparam G_FUNCTION = 3'b100;

//=============================================================================
// RK_SEL
//=============================================================================
localparam COL        = 2'b00;
localparam MIXCOL_IN  = 2'b01;
localparam MIXCOL_OUT = 2'b10;

//=============================================================================
// KEY_OUT_SEL
//=============================================================================
localparam KEY_0 = 2'b00;
localparam KEY_1 = 2'b01;
localparam KEY_2 = 2'b10;
localparam KEY_3 = 2'b11;

//=============================================================================
// COL_SEL
//=============================================================================
localparam SHIFT_ROWS = 2'b00;
localparam ADD_RK_OUT = 2'b01;
localparam INPUT      = 2'b10;

//=============================================================================
// KEY_SEL
//=============================================================================
localparam KEY_HOST = 1'b0;
localparam KEY_OUT  = 1'b1;

//=============================================================================
// KEY_EN
//=============================================================================
localparam KEY_DIS  = 4'b0000;
localparam EN_KEY_0 = 4'b0001;
localparam EN_KEY_1 = 4'b0010;
localparam EN_KEY_2 = 4'b0100;
localparam EN_KEY_3 = 4'b1000;
localparam KEY_ALL  = 4'b1111;

//=============================================================================
// COL_EN
//=============================================================================
localparam COL_DIS  = 4'b0000;
localparam EN_COL_0 = 4'b0001;
localparam EN_COL_1 = 4'b0010;
localparam EN_COL_2 = 4'b0100;
localparam EN_COL_3 = 4'b1000;
localparam COL_ALL  = 4'b1111;

//=============================================================================
// IV_CNT_SEL
//=============================================================================
localparam IV_CNT = 1'b1;
localparam IV_BUS = 1'b0;

//=============================================================================
// ENABLES
//=============================================================================
localparam ENABLE = 1'b1;
localparam DISABLE = 1'b0;

localparam NUMBER_ROUND      = 4'd10;
localparam NUMBER_ROUND_INC  = 4'd11;
localparam INITIAL_ROUND     = 4'd00;

//=============================================================================
// FSM STATES
//=============================================================================
localparam IDLE        = 4'b0000;
localparam ROUND_KEY0  = 4'b0001;
localparam READY       = 4'b0010;
localparam NOP         = 4'b0011;

localparam ROUND0_COL0 = 4'b0100;
localparam ROUND0_COL1 = 4'b0101;
localparam ROUND0_COL2 = 4'b0110;
localparam ROUND0_COL3 = 4'b0111;

localparam ROUND_COL0  = 4'b1000;
localparam ROUND_COL1  = 4'b1001;
localparam ROUND_COL2  = 4'b1010;
localparam ROUND_COL3  = 4'b1011;

localparam GEN_KEY0    = 4'b1100;
localparam GEN_KEY1    = 4'b1101;
localparam GEN_KEY2    = 4'b1110;
localparam GEN_KEY3    = 4'b1111;

reg [3:0] state, next_state;
reg [3:0] rd_count;

wire rd_count_en;
wire op_key_derivation;
wire first_round;
wire [1:0] op_mode;
wire enc_dec;

wire [1:0] phase = state[3:2];
wire [1:0] col_idx = state[1:0];
wire [1:0] col_inc = col_idx + 2'd1;
wire [1:0] col_dec = col_idx - 2'd1;

wire c0 = col_idx[0];
wire c1 = col_idx[1];

wire oh0 = ~c1 & ~c0;
wire oh1 = ~c1 &  c0;
wire oh2 =  c1 & ~c0;
wire oh3 =  c1 &  c0;

wire phase_r0  = ~state[3] &  state[2];
wire phase_rc  =  state[3] & ~state[2];
wire phase_gk  =  state[3] &  state[2];
wire phase_col = phase_r0 | phase_rc;

wire st_round_key0 = (state == ROUND_KEY0);
wire st_ready      = (state == READY);
wire st_gen_key0   = phase_gk & oh0;
wire st_gen_key3   = phase_gk & oh3;
wire gen_key_state = phase_gk;

wire last_round_and_enc_dec;
wire last_round_and_mode_ctr;
wire last_round_special_case;

// State Flops Definition
always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			state <= IDLE;
		else
			if(disable_core)
				state <= IDLE;
			else
				state <= next_state;
	end

assign mode_ctr = aes_mode[1] & ~aes_mode[0];
assign mode_cbc = ~aes_mode[1] & aes_mode[0];

assign op_mode = (mode_ctr) ? ENCRYPTION : operation_mode;

assign encrypt_decrypt = (~op_mode[1]) | gen_key_state;
assign enc_dec = ~op_mode[1];

assign key_gen = st_round_key0;
assign rd_count_en = st_round_key0 | st_gen_key0;

assign op_key_derivation = (~op_mode[1]) & op_mode[0];

assign key_init = start;

assign last_round_and_enc_dec = last_round & enc_dec;
assign last_round_and_mode_ctr = last_round & mode_ctr;
assign last_round_special_case = last_round & ((mode_cbc & ~enc_dec) | mode_ctr);

// Next State Logic
always @(*)
	begin
		next_state = state;

		case(phase)
			2'b01: // ROUND0_COL*
				begin
					if(enc_dec)
						next_state = (col_idx == 2'd3) ? ROUND_KEY0 : {2'b01, col_inc};
					else
						next_state = (col_idx == 2'd0) ? ROUND_KEY0 : {2'b01, col_dec};
				end

			2'b10: // ROUND_COL*
				begin
					if(enc_dec)
						begin
							if(col_idx == 2'd3)
								next_state = (last_round) ? READY : ROUND_KEY0;
							else
								next_state = {2'b10, col_inc};
						end
					else
						begin
							next_state = (col_idx == 2'd0) ? ROUND_KEY0 : {2'b10, col_dec};
						end
				end

			2'b11: // GEN_KEY*
				begin
					if(col_idx == 2'd3)
						begin
							if(last_round)
								next_state = (op_key_derivation) ? READY : ROUND0_COL3;
							else
								next_state = GEN_KEY0;
						end
					else
						next_state = {2'b11, col_inc};
				end

			default:
				begin
					case(state)
						IDLE:
							begin
								if(!start)
									next_state = IDLE;
								else
									case(op_mode)
										ENCRYPTION    : next_state = ROUND0_COL0;
										DECRYPTION    : next_state = ROUND0_COL3;
										KEY_DERIVATION: next_state = GEN_KEY0;
										DECRYP_W_DERIV: next_state = GEN_KEY0;
										default       : next_state = IDLE;
									endcase
							end
						ROUND_KEY0:
							begin
								if(!first_round)
									next_state = (last_round) ? READY : NOP;
								else
									next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
							end
						NOP:
							begin
								next_state = (enc_dec) ? ROUND_COL0 : ROUND_COL3;
							end
						READY:
							begin
								next_state = IDLE;
							end
						default:
							begin
								next_state = IDLE;
							end
					endcase
				end
		endcase
	end

// Shared output equations
wire sbox_is_g = st_round_key0 | st_gen_key0;
wire [2:0] sbox_sel_w = {sbox_is_g, phase_col & c1, phase_col & c0};
wire [1:0] key_out_sel_w = {phase_col & c1, phase_col & c0};

wire [1:0] rk_sel_w = {phase_rc & ~last_round, phase_rc & last_round};

wire bypass_rk_w = phase_r0;
wire bypass_key_en_w = phase_r0 | (phase_gk & ~oh0);

wire key_sel_w = st_round_key0 |
                 phase_rc |
                 (phase_gk & ~oh0) |
                 (phase_r0 & ~enc_dec & ~oh0);

wire [3:0] key_en_w;
assign key_en_w[0] = st_round_key0 | (phase_gk & oh1);
assign key_en_w[1] = (phase_r0 & ~enc_dec & oh1) |
                     (phase_rc & ((enc_dec & oh0) | (~enc_dec & oh1))) |
                     (phase_gk & oh1);
assign key_en_w[2] = (phase_r0 & ~enc_dec & oh2) |
                     (phase_rc & ((enc_dec & oh1) | (~enc_dec & oh2))) |
                     (phase_gk & oh2);
assign key_en_w[3] = (phase_r0 & ~enc_dec & oh3) |
                     (phase_rc & ((enc_dec & oh2) | (~enc_dec & oh3))) |
                     (phase_gk & oh3);

wire r0_add   = phase_r0 & ((enc_dec & oh0) | oh1 | oh2 | (~enc_dec & oh3));
wire r0_shift = phase_r0 & ((~enc_dec & oh0) | (enc_dec & oh3));

wire rc_add   = phase_rc & ~last_round_special_case &
                ((oh0 & (enc_dec | last_round)) |
                 oh1 |
                 oh2 |
                 (oh3 & (~enc_dec | last_round)));

wire rc_shift = phase_rc & ~last_round_special_case &
                ((oh0 & ~enc_dec & ~last_round) |
                 (oh3 &  enc_dec & ~last_round));

wire col_sel_add   = r0_add | rc_add;
wire col_sel_shift = r0_shift | rc_shift;
wire [1:0] col_sel_w = {~(col_sel_add | col_sel_shift), col_sel_add};

wire r0_ce0 = oh0 | (enc_dec & oh3);
wire r0_ce1 = oh1 | (~enc_dec & oh0) | (enc_dec & oh3);
wire r0_ce2 = oh2 | (~enc_dec & oh0) | (enc_dec & oh3);
wire r0_ce3 = oh3 | (~enc_dec & oh0);

wire rc_ce0 = oh0 | (oh3 & enc_dec & ~last_round);
wire rc_ce1 = oh1 | (oh0 & ~enc_dec & ~last_round) | (oh3 & enc_dec & ~last_round);
wire rc_ce2 = oh2 | (oh0 & ~enc_dec & ~last_round) | (oh3 & enc_dec & ~last_round);
wire rc_ce3 = oh3 | (oh0 & ~enc_dec & ~last_round);

wire [3:0] col_en_w;
assign col_en_w[0] = (phase_r0 & r0_ce0) | (phase_rc & rc_ce0);
assign col_en_w[1] = (phase_r0 & r0_ce1) | (phase_rc & rc_ce1);
assign col_en_w[2] = (phase_r0 & r0_ce2) | (phase_rc & rc_ce2);
assign col_en_w[3] = (phase_r0 & r0_ce3) | (phase_rc & rc_ce3);

wire iv_cnt_en_w = phase_rc & oh3 & last_round_and_mode_ctr;
wire iv_cnt_sel_w = phase_rc & oh3 & last_round_and_mode_ctr;

wire key_derivation_en_w = st_ready & op_key_derivation;

// Output Logic
assign end_comp = (state == READY) ? ENABLE : DISABLE;

always @(*)
	begin
		sbox_sel = sbox_sel_w;
		rk_sel = rk_sel_w;
		bypass_rk = bypass_rk_w;
		key_out_sel = key_out_sel_w;
		col_sel = col_sel_w;
		key_sel = key_sel_w;
		key_en = key_en_w;
		col_en = col_en_w;
		iv_cnt_en = iv_cnt_en_w;
		iv_cnt_sel = iv_cnt_sel_w;
		bypass_key_en = bypass_key_en_w;
		key_derivation_en = key_derivation_en_w;
	end

// Round Counter
always @(posedge clk, negedge rst_n)
	begin
		if(!rst_n)
			rd_count <= INITIAL_ROUND;
		else
			if(state == IDLE || (st_gen_key3 && last_round))
				rd_count <= INITIAL_ROUND;
			else 
				if(rd_count_en)
					rd_count <= rd_count + 1'b1;
	end

assign round = rd_count;
assign first_round = ~(|rd_count);
assign last_round  = rd_count[3] & ~rd_count[2] & rd_count[1];

endmodule

