                        read_data <= data_in;
                end
            endcase
        end
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk (clk),
        .rst (rst),
        .baud_division (baud_division),
        .en (enable),
        .baud_tick (baud_tick)
    );

    uart_tx uut_tx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .ext_data_in (data_out),
        .en (enable),
        .tx (tx)
    );

    uart_rx uut_rx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .rx (rx),
        .ext_data_out (data_in)
    );

endmodule


module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            temp_en <= 0;
            delayed_en <= 0;
        end
        else begin
            temp_en <= en;
            delayed_en <= temp_en;
        end
    end

    reg [31:0] baud_count;
    wire baud_div_nz = |baud_division;
    wire edge_detect = en & ~delayed_en & baud_div_nz;
    wire terminal = (baud_count == baud_division) & baud_div_nz;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            baud_count <= 0;
            baud_tick <= 0;
        end
        else if (edge_detect) begin
            baud_count <= 1;
            baud_tick <= baud_tick;
        end
        else if (terminal) begin
            baud_count <= 0;
            baud_tick <= 1;
        end
        else if (baud_div_nz) begin
            baud_count <= baud_count + 1;
            baud_tick <= 0;
        end
        else begin
            baud_count <= 0;
            baud_tick <= 0;
        end
    end

endmodule


module uart_rx (
    input clk,
    input rst,
    input baud_tick,
    input rx,
    output reg [7:0] ext_data_out
);

    reg [3:0] count_16;
    reg count_16_indication;
    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] current_state, next_state;

    wire rx_c16_active = baud_tick & (|current_state);
    wire rx_c16_term = (count_16 == {current_state[1], 3'b111});

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else if (rx_c16_active & rx_c16_term) begin
            count_16 <= 0;
            count_16_indication <= 1;
        end
        else if (rx_c16_active) begin
            count_16 <= count_16 + 1;
            count_16_indication <= 0;
        end
        else if (baud_tick) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else begin
            count_16_indication <= 0;
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;

    always @(posedge clk) begin
        if (current_state == DATA) begin
            if (baud_tick && (&count_16)) begin
                if (&count_8) begin
                    count_8 <= 0;
                    count_8_indication <= 1;
                end
                else begin
                    count_8 <= count_8 + 1;
                    count_8_indication <= 0;
                end
            end
            else begin
                count_8_indication <= 0;
            end
        end
        else begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
    end

    wire do_rx_shift = (current_state == DATA) && baud_tick && (&count_16);

    reg shift_pending;
    reg rx_captured;

    always @(posedge clk or posedge rst) begin
        if (rst)
            shift_pending <= 0;
        else
            shift_pending <= do_rx_shift;
    end

    always @(posedge clk) begin
        if (do_rx_shift)
            rx_captured <= rx;
    end

    always @(posedge clk or posedge rst) begin
        if (rst)
            ext_data_out <= 0;
        else if (shift_pending)
            ext_data_out <= {ext_data_out[6:0], rx_captured};
    end

    always @(posedge clk or posedge rst) begin
        if (rst)
            current_state <= 0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        next_state = current_state;
        if (rst)
            next_state = 0;
        else begin
            case (current_state)
                IDLE: begin
                    if (!rx)
                        next_state = START;
                end
                START: begin
                    if (count_16_indication && !rx)
                        next_state = DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    if (count_16_indication && rx)
                        next_state = IDLE;
                end
            endcase
        end
    end

endmodule


module uart_tx (
    input wire clk,
    input wire rst,
    input wire baud_tick,
    input wire [7:0] ext_data_in,
    input wire en,
    output reg tx
);

    reg [3:0] count_16;
    reg count_16_indication;
    localparam IDLE = 0;
    localparam START = 1;
    localparam DATA = 2;
    localparam STOP = 3;

    reg [1:0] current_state, next_state;

    wire tx_c16_active = baud_tick & (|current_state);

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else if (tx_c16_active & (&count_16)) begin
            count_16 <= 0;
            count_16_indication <= 1;
        end
        else if (tx_c16_active) begin
            count_16 <= count_16 + 1;
            count_16_indication <= 0;
        end
        else if (baud_tick) begin
            count_16 <= 0;
            count_16_indication <= 0;
        end
        else begin
            count_16_indication <= 0;
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    always @(posedge clk) begin
        if (current_state == DATA) begin
            if (baud_tick && (&count_16)) begin
                if (&count_8)
                    count_8_indication <= 1;
                else begin
                    count_8 <= count_8 + 1;
                    count_8_indication <= 0;
                end
            end
            else begin
                count_8_indication <= 0;
            end
        end
        else begin
            count_8 <= 0;
            count_8_indication <= 0;
        end
    end

    always @(posedge clk) begin
        if (current_state != DATA)
            data_save <= ext_data_in;
    end

    always @(posedge clk or posedge rst) begin
        if (rst)
            current_state <= 0;
        else
            current_state <= next_state;
    end

    always @(*) begin
        if (rst)
            next_state = 0;
        else begin
            case (current_state)
                IDLE: begin
                    tx = 1;
                    if (en)
                        next_state = START;
                end
                START: begin
                    tx = 0;
                    if (count_16_indication)
                        next_state = DATA;
                end
                DATA: begin
                    tx = data_save[~count_8];
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    tx = 1;
                    if (count_16_indication)
                        next_state = IDLE;
                end
                default: next_state = IDLE;
            endcase
        end
    end

endmodule

