// ---- file: UART.v0.v ----
module uart_top_design (
    input wire clk,
    input wire rst,
    input wire [1:0] address,
    input wire [31:0] write_data,
    input wire we,
    output wire tx,
    input wire rx,
    input wire re,
    output reg [7:0] read_data
);

    localparam BAUD_DATA = 2'd0;
    localparam ENABLE    = 2'd1;
    localparam TX_DATA   = 2'd2;
    localparam RX_DATA   = 2'd3;

    reg [31:0] baud_division_reg;
    reg enable_reg;
    reg [7:0] data_out_reg;
    wire [7:0] data_in;

    wire wr_baud = we && (address == BAUD_DATA);
    wire wr_en   = we && (address == ENABLE);
    wire wr_tx   = we && (address == TX_DATA);

    wire [31:0] baud_division = rst ? 32'b0 : (wr_baud ? write_data : baud_division_reg);
    wire enable = rst ? 1'b0 : (wr_en ? write_data[0] : enable_reg);
    wire [7:0] data_out = rst ? 8'b0 : (wr_tx ? write_data[7:0] : data_out_reg);

    always @(posedge clk) begin
        if (rst)
            baud_division_reg <= 32'b0;
        else if (wr_baud)
            baud_division_reg <= write_data;
    end

    always @(posedge clk) begin
        if (rst)
            enable_reg <= 1'b0;
        else if (wr_en)
            enable_reg <= write_data[0];
    end

    always @(posedge clk) begin
        if (rst)
            data_out_reg <= 8'b0;
        else if (wr_tx)
            data_out_reg <= write_data[7:0];
    end

    always @(*) begin
        if (!rst && re && (address == RX_DATA))
            read_data <= data_in;
    end

    wire baud_tick;

    uart_baud_rate uut_baud_rate (
        .clk (clk),
        .rst (rst),
        .baud_division (baud_division),
        .en (enable),
        .baud_tick (baud_tick)
    );

    uart_tx uut_tx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .ext_data_in (data_out),
        .en (enable),
        .tx (tx)
    );

    uart_rx uut_rx (
        .clk (clk),
        .rst (rst),
        .baud_tick (baud_tick),
        .rx (rx),
        .ext_data_out (data_in)
    );

endmodule



module uart_baud_rate (
    input wire clk,
    input wire rst,
    input wire [31:0] baud_division,
    input wire en,
    output reg baud_tick
);

    reg temp_en;
    reg delayed_en;

    always @(posedge clk) begin
        if (rst) begin
            temp_en <= 1'b0;
            delayed_en <= 1'b0;
        end
        else begin
            temp_en <= en;
            delayed_en <= temp_en;
        end
    end

    reg [31:0] baud_count;

    always @(posedge clk) begin
        if (rst) begin
            baud_count <= 32'b0;
            baud_tick <= 1'b0;
        end
        else begin
            if (|baud_division) begin
                if (en && !delayed_en) begin
                    baud_count <= 32'd1;
                end
                else if (baud_count == baud_division) begin
                    baud_count <= 32'b0;
                    baud_tick <= 1'b1;
                end
                else begin
                    baud_count <= baud_count + 32'd1;
                    baud_tick <= 1'b0;
                end
            end
            else begin
                baud_count <= 32'b0;
                baud_tick <= 1'b0;
            end
        end
    end

endmodule



module uart_rx (
    input clk,
    input rst,
    input baud_tick,
    input rx,
    output reg [7:0] ext_data_out
);

    reg [3:0] count_16;
    reg count_16_indication;

    localparam IDLE  = 2'd0;
    localparam START = 2'd1;
    localparam DATA  = 2'd2;
    localparam STOP  = 2'd3;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'b0;
            count_16_indication <= 1'b0;
        end
        else begin
            if (baud_tick) begin
                if (current_state == START) begin
                    if (count_16 == 4'd7) begin
                        count_16 <= 4'b0;
                        count_16_indication <= 1'b1;
                    end
                    else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end
                else if ((current_state == DATA) || (current_state == STOP)) begin
                    if (count_16 == 4'd15) begin
                        count_16 <= 4'b0;
                        count_16_indication <= 1'b1;
                    end
                    else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end
                else begin
                    count_16 <= 4'b0;
                    count_16_indication <= 1'b0;
                end
            end
            else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 3'b0;
            count_8_indication <= 1'b0;
            data_save <= 8'b0;
        end
        else begin
            if (current_state == DATA) begin
                if (baud_tick && (count_16 == 4'd15)) begin
                    data_save <= {data_save[6:0], rx};
                    if (count_8 == 3'd7) begin
                        count_8 <= 3'b0;
                        count_8_indication <= 1'b1;
                    end
                    else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                    end
                end
                else begin
                    count_8_indication <= 1'b0;
                end
            end
            else begin
                count_8 <= 3'b0;
                count_8_indication <= 1'b0;
            end
        end
    end

    always @(posedge clk) begin
        if (rst)
            ext_data_out <= 8'b0;
        else
            ext_data_out <= data_save;
    end

    always @(posedge clk) begin
        if (rst)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        next_state = current_state;
        if (rst) begin
            next_state = IDLE;
        end
        else begin
            case (current_state)
                IDLE: begin
                    if (!rx)
                        next_state = START;
                end
                START: begin
                    if (count_16_indication && !rx)
                        next_state = DATA;
                end
                DATA: begin
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    if (count_16_indication && rx)
                        next_state = IDLE;
                end
                default: next_state = IDLE;
            endcase
        end
    end

endmodule



module uart_tx (
    input wire clk,
    input wire rst,
    input wire baud_tick,
    input wire [7:0] ext_data_in,
    input wire en,
    output reg tx
);

    reg [3:0] count_16;
    reg count_16_indication;

    localparam IDLE  = 2'd0;
    localparam START = 2'd1;
    localparam DATA  = 2'd2;
    localparam STOP  = 2'd3;

    reg [1:0] current_state, next_state;

    always @(posedge clk) begin
        if (rst) begin
            count_16 <= 4'b0;
            count_16_indication <= 1'b0;
        end
        else begin
            if (baud_tick) begin
                if (current_state != IDLE) begin
                    if (count_16 == 4'd15) begin
                        count_16 <= 4'b0;
                        count_16_indication <= 1'b1;
                    end
                    else begin
                        count_16 <= count_16 + 4'd1;
                        count_16_indication <= 1'b0;
                    end
                end
                else begin
                    count_16 <= 4'b0;
                    count_16_indication <= 1'b0;
                end
            end
            else begin
                count_16_indication <= 1'b0;
            end
        end
    end

    reg [2:0] count_8;
    reg count_8_indication;
    reg [7:0] data_save;

    always @(posedge clk) begin
        if (rst) begin
            count_8 <= 3'b0;
            count_8_indication <= 1'b0;
            data_save <= 8'b0;
        end
        else begin
            if (current_state == DATA) begin
                if (baud_tick && (count_16 == 4'd15)) begin
                    if (count_8 == 3'd7) begin
                        count_8 <= 3'b0;
                        count_8_indication <= 1'b1;
                    end
                    else begin
                        count_8 <= count_8 + 3'd1;
                        count_8_indication <= 1'b0;
                        data_save <= {data_save[6:0], 1'b0};
                    end
                end
                else begin
                    count_8_indication <= 1'b0;
                end
            end
            else begin
                count_8 <= 3'b0;
                count_8_indication <= 1'b0;
                if (en || (current_state != IDLE))
                    data_save <= ext_data_in;
            end
        end
    end

    always @(posedge clk) begin
        if (rst)
            current_state <= IDLE;
        else
            current_state <= next_state;
    end

    always @(*) begin
        next_state = current_state;
        if (rst) begin
            next_state = IDLE;
        end
        else begin
            case (current_state)
                IDLE: begin
                    tx = 1'b1;
                    if (en)
                        next_state = START;
                end
                START: begin
                    tx = 1'b0;
                    if (count_16_indication)
                        next_state = DATA;
                end
                DATA: begin
                    tx = data_save[7];
                    if (count_8_indication)
                        next_state = STOP;
                end
                STOP: begin
                    tx = 1'b1;
                    if (count_16_indication)
                        next_state = IDLE;
                end
                default: next_state = IDLE;
            endcase
        end
    end

endmodule

